def get_today_top_events(workspace_id, limit=None, type=None, cache_ttl_seconds=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _ms():
        return int((time.time() - t0) * 1000)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int.from_bytes(os.urandom(11), "big")
        out = []
        for _ in range(17):
            x, r = divmod(x, 36)
            out.append(alphabet[r])
        return prefix + "_" + "".join(reversed(out))

    def _canonical_json(obj):
        if obj is None:
            obj = {}
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _cache_key(ws_id, qtype, params):
        h = hashlib.sha256((ws_id + "|" + qtype + "|" + _canonical_json(params)).encode("utf-8")).hexdigest()
        return "ck_" + h

    def _evict_expired(results):
        changed = False
        for r in results:
            if r.get("status") == "fresh" and r.get("expires_at"):
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp <= now_dt:
                    r["status"] = "stale"
                    r["updated_at"] = now_iso
                    changed = True
        if changed:
            _save("analytics_query_results.json", results)

    def _pick_authorized_context(ws_id):
        # Ambient auth: choose any active API key for this workspace that can perform read reports.
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws:
            return None, None, None, _err("NOT_FOUND", "Workspace connection not found.", workspace_id=ws_id)
        keys = _load("workspace_api_keys.json")
        candidates = []
        for k in keys:
            if k.get("workspace_id") != ws_id:
                continue
            if k.get("status") != "active":
                continue
            scopes = k.get("scopes") or []
            if isinstance(scopes, list) and ("read:reports" in scopes):
                candidates.append(k)
        if candidates:
            # choose the one with highest limits to reduce chance of rate limiting
            candidates.sort(key=lambda r: (int(r.get("rate_limit_per_minute") or 0), int(r.get("daily_quota") or 0)), reverse=True)
            return ws, candidates[0], workspaces, None
        # If there is no key, still allow the call as "ambient" only if any key exists at all for the workspace
        # (real service would require a key; here we return UNAUTHORIZED only if no combination can serve).
        any_key = next((k for k in keys if k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if any_key:
            return ws, any_key, workspaces, None
        return None, None, None, _err("UNAUTHORIZED", "No active API key available to serve this request for the workspace.", workspace_id=ws_id)

    def _check_limits(api_key_row, queries_rows):
        if not api_key_row:
            return None
        key_id = api_key_row.get("id")
        if not key_id:
            return _err("UNAUTHORIZED", "API key context missing.")
        rpm = api_key_row.get("rate_limit_per_minute")
        dq = api_key_row.get("daily_quota")
        try:
            rpm = int(rpm)
            dq = int(dq)
        except Exception:
            return _err("VALIDATION_ERROR", "API key limits misconfigured.", api_key_id=key_id)

        window_1m = now_dt - datetime.timedelta(minutes=1)
        window_1d = now_dt - datetime.timedelta(days=1)
        c1m = 0
        c1d = 0
        for q in queries_rows:
            if q.get("api_key_id") != key_id:
                continue
            ca = _parse_dt(q.get("created_at"))
            if not ca:
                continue
            if ca >= window_1m:
                c1m += 1
            if ca >= window_1d:
                c1d += 1
        if c1m >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", api_key_id=key_id, limit_per_minute=rpm)
        if c1d >= dq:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", api_key_id=key_id, daily_quota=dq)
        return None

    # Validate
    # IMPORTANT: datastore contains ids longer than 17; accept those too while still validating shape/prefix.
    if not isinstance(workspace_id, str) or not re.fullmatch(r"^mix_ws_[0-9A-Z]{17,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or not (1 <= limit <= 1000):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.")
    if type is None:
        type = "general"
    if type not in ("general", "unique"):
        return _err("VALIDATION_ERROR", "type must be one of: general, unique.")
    if cache_ttl_seconds is None:
        cache_ttl_seconds = 0
    if not isinstance(cache_ttl_seconds, int) or not (0 <= cache_ttl_seconds <= 2592000):
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer between 0 and 2592000.")

    params = {"workspace_id": workspace_id, "limit": limit, "type": type, "cache_ttl_seconds": cache_ttl_seconds}

    # Resolve context
    ws, api_key, workspaces_rows, ctx_err = _pick_authorized_context(workspace_id)
    if ctx_err:
        return ctx_err

    # Always create analytics_queries row for the tool call
    queries = _load("analytics_queries.json")
    results = _load("analytics_query_results.json")
    _evict_expired(results)

    ck = None
    ttl = None
    if cache_ttl_seconds and cache_ttl_seconds > 0:
        ck = _cache_key(workspace_id, "events.top", {"day": "today", "limit": limit, "type": type})
        ttl = cache_ttl_seconds

        # Return cached fresh result if exists
        for r in results:
            if r.get("cache_key") == ck and r.get("workspace_id") == workspace_id and r.get("status") == "fresh":
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp > now_dt:
                    qid = _gen_id("mix_qry")
                    qrow = {
                        "id": qid,
                        "workspace_id": workspace_id,
                        "api_key_id": api_key.get("id") if api_key else None,
                        "tool_name": "get_today_top_events",
                        "query_type": "events.top",
                        "parameters": params,
                        "mixpanel_request": None,
                        "cache_key": ck,
                        "cache_ttl_seconds": ttl,
                        "status": "succeeded",
                        "started_at": now_iso,
                        "completed_at": now_iso,
                        "duration_ms": 0,
                        "http_status": 200,
                        "error_code": None,
                        "error_message": None,
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    queries.append(qrow)
                    _save("analytics_queries.json", queries)
                    if api_key:
                        api_key["last_used_at"] = now_iso
                        api_key["updated_at"] = now_iso
                        keys = _load("workspace_api_keys.json")
                        for i, k in enumerate(keys):
                            if k.get("id") == api_key.get("id"):
                                keys[i] = api_key
                                _save("workspace_api_keys.json", keys)
                                break
                    payload = r.get("result_json") if r.get("content_type") == "application/json" else {"text": r.get("result_text")}
                    return {
                        "query": qrow,
                        "cached": True,
                        "data": payload,
                        "meta": {"latency_ms": _ms()},
                    }

    # Enforce workspace active for Mixpanel reads (this tool is a Mixpanel read)
    qid = _gen_id("mix_qry")
    qrow = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": api_key.get("id") if api_key else None,
        "tool_name": "get_today_top_events",
        "query_type": "events.top",
        "parameters": params,
        "mixpanel_request": {"endpoint": "/events/top", "querystring": {"day": "today", "limit": limit, "type": type}, "region": ws.get("region")},
        "cache_key": ck,
        "cache_ttl_seconds": ttl,
        "status": "queued",
        "started_at": None,
        "completed_at": None,
        "duration_ms": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Rate limit/quota: check before running; if exceeded, record failed query
    lim_err = _check_limits(api_key, queries)
    if lim_err:
        qrow["status"] = "failed"
        qrow["started_at"] = now_iso
        qrow["completed_at"] = now_iso
        qrow["duration_ms"] = 0
        qrow["error_code"] = lim_err["error"]["code"].lower()
        qrow["error_message"] = lim_err["error"]["message"]
        qrow["updated_at"] = now_iso
        queries.append(qrow)
        _save("analytics_queries.json", queries)
        return lim_err

    queries.append(qrow)
    _save("analytics_queries.json", queries)

    # queued -> running
    qrow["status"] = "running"
    qrow["started_at"] = now_iso
    qrow["updated_at"] = now_iso
    for i in range(len(queries) - 1, -1, -1):
        if queries[i].get("id") == qid:
            queries[i] = qrow
            _save("analytics_queries.json", queries)
            break

    if ws.get("status") != "active":
        qrow["status"] = "failed"
        qrow["completed_at"] = now_iso
        qrow["duration_ms"] = _ms()
        qrow["http_status"] = 424
        qrow["error_code"] = "workspace_inactive"
        qrow["error_message"] = "Workspace connection is not active; refusing to contact Mixpanel."
        qrow["updated_at"] = now_iso
        for i in range(len(queries) - 1, -1, -1):
            if queries[i].get("id") == qid:
                queries[i] = qrow
                _save("analytics_queries.json", queries)
                break
        return _err("INVALID_TRANSITION", qrow["error_message"], workspace_id=workspace_id, workspace_status=ws.get("status"))

    # "Call Mixpanel" (offline): produce deterministic synthetic but stable payload based on workspace + params
    seed = hashlib.sha256((workspace_id + "|today|" + type).encode("utf-8")).hexdigest()
    rows = []
    for i in range(limit):
        # generate pseudo counts
        c = int(seed[i % len(seed)], 16) * (limit - i)
        rows.append({"event": f"Event {i+1}", "count": c})
        if i >= min(limit, 20) - 1 and limit > 20:
            # don't bloat results; cap at 200 in stored mock payload
            if i >= 199:
                break
    data = {"day": "today", "type": type, "results": rows[:limit]}

    # succeeded + store result
    qrow["status"] = "succeeded"
    qrow["completed_at"] = now_iso
    qrow["duration_ms"] = _ms()
    qrow["http_status"] = 200
    qrow["updated_at"] = now_iso
    for i in range(len(queries) - 1, -1, -1):
        if queries[i].get("id") == qid:
            queries[i] = qrow
            _save("analytics_queries.json", queries)
            break

    res_id = _gen_id("mix_res")
    expires_at = None
    if cache_ttl_seconds and cache_ttl_seconds > 0:
        expires_at = (now_dt + datetime.timedelta(seconds=cache_ttl_seconds)).isoformat() + "Z"
    res_row = {
        "id": res_id,
        "query_id": qid,
        "workspace_id": workspace_id,
        "cache_key": ck,
        "content_type": "application/json",
        "result_json": data,
        "result_text": None,
        "result_bytes": len(json.dumps(data, ensure_ascii=False).encode("utf-8")),
        "status": "fresh" if expires_at else "fresh",
        "expires_at": expires_at,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    # unique(query_id)
    if any(r.get("query_id") == qid for r in results):
        return _err("CONFLICT", "Result for query already exists (unique(query_id)).", query_id=qid)
    results.append(res_row)
    _save("analytics_query_results.json", results)

    if api_key:
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        keys = _load("workspace_api_keys.json")
        for i, k in enumerate(keys):
            if k.get("id") == api_key.get("id"):
                keys[i] = api_key
                _save("workspace_api_keys.json", keys)
                break

    return {"query": qrow, "cached": False, "data": data, "meta": {"latency_ms": _ms()}}

def profile_event_activity(workspace_id, distinct_id, from_date=None, to_date=None, limit=None, cursor=None, cache_ttl_seconds=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _ms():
        return int((time.time() - t0) * 1000)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _parse_date(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int.from_bytes(os.urandom(11), "big")
        out = []
        for _ in range(17):
            x, r = divmod(x, 36)
            out.append(alphabet[r])
        return prefix + "_" + "".join(reversed(out))

    def _canonical_json(obj):
        if obj is None:
            obj = {}
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _cache_key(ws_id, qtype, params):
        h = hashlib.sha256((ws_id + "|" + qtype + "|" + _canonical_json(params)).encode("utf-8")).hexdigest()
        return "ck_" + h

    def _evict_expired(results):
        changed = False
        for r in results:
            if r.get("status") == "fresh" and r.get("expires_at"):
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp <= now_dt:
                    r["status"] = "stale"
                    r["updated_at"] = now_iso
                    changed = True
        if changed:
            _save("analytics_query_results.json", results)

    def _pick_authorized_context(ws_id):
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws:
            return None, None, _err("NOT_FOUND", "Workspace connection not found.", workspace_id=ws_id)
        keys = _load("workspace_api_keys.json")
        candidates = []
        for k in keys:
            if k.get("workspace_id") != ws_id or k.get("status") != "active":
                continue
            scopes = k.get("scopes") or []
            if isinstance(scopes, list) and ("read:profiles" in scopes):
                candidates.append(k)
        if candidates:
            candidates.sort(key=lambda r: (int(r.get("rate_limit_per_minute") or 0), int(r.get("daily_quota") or 0)), reverse=True)
            return ws, candidates[0], None
        any_key = next((k for k in keys if k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if any_key:
            return ws, any_key, None
        return None, None, _err("UNAUTHORIZED", "No active API key available to serve this request for the workspace.", workspace_id=ws_id)

    def _check_limits(api_key_row, queries_rows):
        if not api_key_row:
            return None
        key_id = api_key_row.get("id")
        if not key_id:
            return _err("UNAUTHORIZED", "API key context missing.")
        rpm = api_key_row.get("rate_limit_per_minute")
        dq = api_key_row.get("daily_quota")
        try:
            rpm = int(rpm)
            dq = int(dq)
        except Exception:
            return _err("VALIDATION_ERROR", "API key limits misconfigured.", api_key_id=key_id)

        window_1m = now_dt - datetime.timedelta(minutes=1)
        window_1d = now_dt - datetime.timedelta(days=1)
        c1m = 0
        c1d = 0
        for q in queries_rows:
            if q.get("api_key_id") != key_id:
                continue
            ca = _parse_dt(q.get("created_at"))
            if not ca:
                continue
            if ca >= window_1m:
                c1m += 1
            if ca >= window_1d:
                c1d += 1
        if c1m >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", api_key_id=key_id, limit_per_minute=rpm)
        if c1d >= dq:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", api_key_id=key_id, daily_quota=dq)
        return None

    # Validate (accept ids longer than 17 to match actual datastore)
    if not isinstance(workspace_id, str) or not re.fullmatch(r"^mix_ws_[0-9A-Z]{17,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(distinct_id, str) or distinct_id.strip() == "":
        return _err("VALIDATION_ERROR", "distinct_id must be a non-empty string.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or not (1 <= limit <= 10000):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 10000.")
    fd = _parse_date(from_date) if from_date is not None else None
    td = _parse_date(to_date) if to_date is not None else None
    if from_date is not None and not fd:
        return _err("VALIDATION_ERROR", "from_date must be YYYY-MM-DD.")
    if to_date is not None and not td:
        return _err("VALIDATION_ERROR", "to_date must be YYYY-MM-DD.")
    if fd and td and fd > td:
        return _err("VALIDATION_ERROR", "from_date must be on or before to_date.")
    if cache_ttl_seconds is None:
        cache_ttl_seconds = 0
    if not isinstance(cache_ttl_seconds, int) or not (0 <= cache_ttl_seconds <= 2592000):
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer between 0 and 2592000.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("c:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    params = {
        "workspace_id": workspace_id,
        "distinct_id": distinct_id,
        "from_date": from_date,
        "to_date": to_date,
        "limit": limit,
        "cursor": cursor,
        "cache_ttl_seconds": cache_ttl_seconds,
    }

    ws, api_key, ctx_err = _pick_authorized_context(workspace_id)
    if ctx_err:
        return ctx_err

    queries = _load("analytics_queries.json")
    results = _load("analytics_query_results.json")
    _evict_expired(results)

    ck = None
    ttl = None
    if cache_ttl_seconds and cache_ttl_seconds > 0:
        ck = _cache_key(workspace_id, "profiles.activity", {"distinct_id": distinct_id, "from_date": from_date, "to_date": to_date, "limit": limit, "offset": offset})
        ttl = cache_ttl_seconds
        for r in results:
            if r.get("cache_key") == ck and r.get("workspace_id") == workspace_id and r.get("status") == "fresh":
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp > now_dt:
                    qid = _gen_id("mix_qry")
                    qrow = {
                        "id": qid,
                        "workspace_id": workspace_id,
                        "api_key_id": api_key.get("id") if api_key else None,
                        "tool_name": "profile_event_activity",
                        "query_type": "profiles.activity",
                        "parameters": params,
                        "mixpanel_request": None,
                        "cache_key": ck,
                        "cache_ttl_seconds": ttl,
                        "status": "succeeded",
                        "started_at": now_iso,
                        "completed_at": now_iso,
                        "duration_ms": 0,
                        "http_status": 200,
                        "error_code": None,
                        "error_message": None,
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    queries.append(qrow)
                    _save("analytics_queries.json", queries)
                    if api_key:
                        api_key["last_used_at"] = now_iso
                        api_key["updated_at"] = now_iso
                        keys = _load("workspace_api_keys.json")
                        for i, k in enumerate(keys):
                            if k.get("id") == api_key.get("id"):
                                keys[i] = api_key
                                _save("workspace_api_keys.json", keys)
                                break
                    payload = r.get("result_json") if r.get("content_type") == "application/json" else {"text": r.get("result_text")}
                    return {"query": qrow, "cached": True, "data": payload, "meta": {"latency_ms": _ms()}}

    qid = _gen_id("mix_qry")
    qrow = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": api_key.get("id") if api_key else None,
        "tool_name": "profile_event_activity",
        "query_type": "profiles.activity",
        "parameters": params,
        "mixpanel_request": {"endpoint": "/engage/events", "querystring": {"distinct_id": distinct_id, "from_date": from_date, "to_date": to_date, "limit": limit, "offset": offset}, "region": ws.get("region")},
        "cache_key": ck,
        "cache_ttl_seconds": ttl,
        "status": "queued",
        "started_at": None,
        "completed_at": None,
        "duration_ms": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    lim_err = _check_limits(api_key, queries)
    if lim_err:
        qrow["status"] = "failed"
        qrow["started_at"] = now_iso
        qrow["completed_at"] = now_iso
        qrow["duration_ms"] = 0
        qrow["error_code"] = lim_err["error"]["code"].lower()
        qrow["error_message"] = lim_err["error"]["message"]
        qrow["updated_at"] = now_iso
        queries.append(qrow)
        _save("analytics_queries.json", queries)
        return lim_err

    queries.append(qrow)
