    def _find_workspace(ws_id):
        if not isinstance(ws_id, str) or not re.match(r"^mix_ws_[0-9A-Z]{17}$", ws_id):
            return None, _err("VALIDATION_ERROR", "workspace_id is malformed; expected ^mix_ws_[0-9A-Z]{17}$.")
