        for w in workspaces:
            if w.get("id") == ws_id:
                return w, None
        return None, _err("NOT_FOUND", "workspace_id not found.", workspace_id=ws_id)

    def _count_key_usage(queries_rows, api_key_id):
        # Rate limit: last minute, Quota: today (UTC) as per store timestamps
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        today_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        minute_n = 0
        day_n = 0
        for q in queries_rows:
            if q.get("api_key_id") != api_key_id:
                continue
            created = _parse_dt(q.get("created_at"))
            if not created:
                continue
            if created >= one_min_ago:
                minute_n += 1
            if created >= today_start:
                day_n += 1
        return minute_n, day_n

    def _pick_api_key_for_workspace(ws_id, required_scope):
        # Ambient auth: pick an active key for the workspace that can serve this call.
        keys = _load("workspace_api_keys.json")
