        for k in keys:
            if k.get("workspace_id") != ws_id:
                continue
            if k.get("status") != "active":
                continue
            scopes = k.get("scopes") or []
            if required_scope not in scopes:
                continue
            # Validate limits presence/types
            rl = k.get("rate_limit_per_minute")
            dq = k.get("daily_quota")
            if not isinstance(rl, int) or not isinstance(dq, int):
                continue
            candidates.append(k)
        if not candidates:
            return None
        # Prefer highest limits to reduce accidental rate-limit selection
        candidates.sort(key=lambda r: (r.get("daily_quota", 0), r.get("rate_limit_per_minute", 0)), reverse=True)
