    def _update_query_status(queries_rows, qid, new_status, **updates):
        allowed = {
            "queued": set(["running", "cancelled"]),
            "running": set(["succeeded", "failed", "cancelled"]),
            "succeeded": set([]),
            "failed": set([]),
            "cancelled": set([])
        }
        q = None
        for r in queries_rows:
            if r.get("id") == qid:
                q = r
                break
        if q is None:
            return False, _err("NOT_FOUND", "analytics query not found.", query_id=qid)
        old = q.get("status")
        if old not in allowed or new_status not in allowed.get(old, set()):
            return False, _err("INVALID_TRANSITION", "Invalid analytics_queries status transition.", from_status=old, to_status=new_status, query_id=qid)
        q["status"] = new_status
        for k, v in updates.items():
            q[k] = v
        q["updated_at"] = now_iso
        _save("analytics_queries.json", queries_rows)
        return True, q

    def _create_result_row(query_row, payload, cache_key, cache_ttl):
        results = _load("analytics_query_results.json")
