        res_id = _gen_id("mix_res")
        content_type = "application/json"
        result_json = payload
        result_text = None
        body = json.dumps(payload, ensure_ascii=False)
        result_bytes = len(body.encode("utf-8"))

        expires_at = None
        if isinstance(cache_ttl, int) and cache_ttl > 0:
