        row = {
            "id": res_id,
            "query_id": query_row.get("id"),
            "workspace_id": query_row.get("workspace_id"),
            "cache_key": cache_key,
            "content_type": content_type,
            "result_json": result_json,
            "result_text": result_text,
            "result_bytes": result_bytes,
            "status": "fresh",
            "expires_at": expires_at,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        results.append(row)
        _save("analytics_query_results.json", results)
        return row, None

    # --------- Validate inputs ----------
    ws, ws_err = _find_workspace(workspace_id)
    if ws_err:
        # Must still record a query row per business rule
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
