        }
        qrow, queries_rows = _store_query_row(params, workspace_id if isinstance(workspace_id, str) else "", None, None, cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else None)
        # queued->running->failed
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), http_status=None, error_code=ws_err["error"]["code"], error_message=ws_err["error"]["message"])
