        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="VALIDATION_ERROR", error_message="from_date and to_date must be strings in YYYY-MM-DD.")
        return _err("VALIDATION_ERROR", "from_date and to_date must be strings in YYYY-MM-DD.")

    fd = _parse_date(from_date)
    td = _parse_date(to_date)
    if not fd or not td:
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
            "cache_ttl_seconds": cache_ttl_seconds
        }
        qrow, queries_rows = _store_query_row(params, workspace_id, None, None, cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else None)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="VALIDATION_ERROR", error_message="Dates must be in YYYY-MM-DD.")
        return _err("VALIDATION_ERROR", "Dates must be in YYYY-MM-DD.", from_date=from_date, to_date=to_date)

    if fd > td:
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
            "cache_ttl_seconds": cache_ttl_seconds
        }
        qrow, queries_rows = _store_query_row(params, workspace_id, None, None, cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else None)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="VALIDATION_ERROR", error_message="from_date must be <= to_date.")
        return _err("VALIDATION_ERROR", "from_date must be <= to_date.", from_date=from_date, to_date=to_date)

    if unit not in ("day", "week", "month"):
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
