        }
        qrow, queries_rows = _store_query_row(params, workspace_id, None, None, cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else None)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="VALIDATION_ERROR", error_message="unit must be one of: day, week, month.")
        return _err("VALIDATION_ERROR", "unit must be one of: day, week, month.")

    if type not in ("general", "unique", "average"):
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
            "cache_ttl_seconds": cache_ttl_seconds
        }
        qrow, queries_rows = _store_query_row(params, workspace_id, None, None, cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else None)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="VALIDATION_ERROR", error_message="type must be one of: general, unique, average.")
        return _err("VALIDATION_ERROR", "type must be one of: general, unique, average.")

    # IMPORTANT: Accept both `event` and `events` if provided; do not reject (audit defect).
    event_names = []
    if isinstance(events, list) and len(events) > 0:
        for e in events:
            if isinstance(e, str) and e.strip() != "":
                event_names.append(e)
            else:
                params = {
                    "workspace_id": workspace_id,
                    "event": event,
                    "events": events,
