                }
                qrow, queries_rows = _store_query_row(params, workspace_id, None, None, cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else None)
                _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
                _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="VALIDATION_ERROR", error_message="events must be an array of non-empty strings.")
                return _err("VALIDATION_ERROR", "events must be an array of non-empty strings.")
    if isinstance(event, str) and event.strip() != "":
        # Prepend single event if not already present
        if event not in event_names:
            event_names.insert(0, event)
    if not event_names:
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
            "cache_ttl_seconds": cache_ttl_seconds
        }
        qrow, queries_rows = _store_query_row(params, workspace_id, None, None, cache_ttl_seconds if isinstance(cache_ttl_seconds, int) else None)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="VALIDATION_ERROR", error_message="Provide at least one event via 'event' or 'events'.")
        return _err("VALIDATION_ERROR", "Provide at least one event via 'event' or 'events'.")

    if cache_ttl_seconds is None:
        cache_ttl_seconds = 0
    if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 0 or cache_ttl_seconds > 2592000:
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
            "cache_ttl_seconds": cache_ttl_seconds
        }
        qrow, queries_rows = _store_query_row(params, workspace_id, None, None, None)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="VALIDATION_ERROR", error_message="cache_ttl_seconds must be an integer between 0 and 2592000.")
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer between 0 and 2592000.")

    # Workspace must be active before "contacting Mixpanel" (even though offline, enforce rule)
    if ws.get("status") != "active":
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
            "cache_ttl_seconds": cache_ttl_seconds
        }
        qrow, queries_rows = _store_query_row(params, workspace_id, None, None, cache_ttl_seconds)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(
            queries_rows,
            qrow["id"],
            "failed",
            completed_at=now_iso,
            duration_ms=_ms(),
            http_status=None,
            error_code="workspace_inactive",
            error_message=f"Workspace status is '{ws.get('status')}', must be 'active'."
        )
        return _err("INVALID_TRANSITION", "Workspace is not active; cannot execute Mixpanel queries.", workspace_id=workspace_id, status=ws.get("status"))

    # Pick an ambient API key with appropriate scope for this operation
    required_scope = "read:reports"
    api_key = _pick_api_key_for_workspace(workspace_id, required_scope)
    if not api_key:
        # No credential combination can serve call
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
            "cache_ttl_seconds": cache_ttl_seconds
        }
        qrow, queries_rows = _store_query_row(params, workspace_id, None, None, cache_ttl_seconds)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="UNAUTHORIZED", error_message="No active API key with required scope read:reports.")
        return _err("UNAUTHORIZED", "No active API key available with required scope for this workspace.", required_scope=required_scope, workspace_id=workspace_id)

    # Enforce rate limits/quotas against analytics_queries created for this api_key
    queries_existing = _load("analytics_queries.json")
    minute_n, day_n = _count_key_usage(queries_existing, api_key.get("id"))
    if minute_n >= int(api_key.get("rate_limit_per_minute", 0)):
        # Don't create a succeeded query; create a failed query row
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
            "cache_ttl_seconds": cache_ttl_seconds
        }
        qrow, queries_rows = _store_query_row(params, workspace_id, api_key.get("id"), None, cache_ttl_seconds)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="RATE_LIMIT", error_message="Rate limit exceeded for this API key.")
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", api_key_id=api_key.get("id"), rate_limit_per_minute=api_key.get("rate_limit_per_minute"))

    if day_n >= int(api_key.get("daily_quota", 0)):
        params = {
            "workspace_id": workspace_id,
            "event": event,
            "events": events,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "type": type,
            "cache_ttl_seconds": cache_ttl_seconds
        }
        qrow, queries_rows = _store_query_row(params, workspace_id, api_key.get("id"), None, cache_ttl_seconds)
        _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code="QUOTA_EXCEEDED", error_message="Daily quota exceeded for this API key.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", api_key_id=api_key.get("id"), daily_quota=api_key.get("daily_quota"))

    # Compute cache key if caching enabled
    tool_params = {
        "workspace_id": workspace_id,
        "event": event,
        "events": events,
        "from_date": from_date,
        "to_date": to_date,
        "unit": unit,
        "type": type,
        "cache_ttl_seconds": cache_ttl_seconds
    }
    cache_key = None
    if isinstance(cache_ttl_seconds, int) and cache_ttl_seconds > 0:
        cache_key = _cache_key(workspace_id, "events.aggregate", tool_params)

    # Cache retrieval
    results_rows = _load("analytics_query_results.json")
    _evict_expired(results_rows)
    if cache_key:
        for r in results_rows:
            if r.get("cache_key") == cache_key and r.get("status") == "fresh":
                exp = _parse_dt(r.get("expires_at")) if r.get("expires_at") else None
                if exp and exp > now_dt:
                    # Still must record analytics_queries row for every call
                    qrow, queries_rows = _store_query_row(tool_params, workspace_id, api_key.get("id"), cache_key, cache_ttl_seconds)
                    _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
                    _update_query_status(queries_rows, qrow["id"], "succeeded", completed_at=now_iso, duration_ms=_ms(), http_status=200)
                    # Update key last_used_at on success
                    keys = _load("workspace_api_keys.json")
                    for k in keys:
                        if k.get("id") == api_key.get("id"):
                            k["last_used_at"] = now_iso
                            k["updated_at"] = now_iso
                            break
                    _save("workspace_api_keys.json", keys)
                    return {
                        "query": qrow,
                        "cached_result": {
                            "id": r.get("id"),
                            "query_id": r.get("query_id"),
                            "status": r.get("status"),
                            "expires_at": r.get("expires_at"),
                            "content_type": r.get("content_type"),
                            "result_bytes": r.get("result_bytes")
                        },
                        "data": r.get("result_json") if r.get("content_type") == "application/json" else r.get("result_text")
                    }

    # Create query row, run, then store result
    qrow, queries_rows = _store_query_row(tool_params, workspace_id, api_key.get("id"), cache_key, cache_ttl_seconds)
    ok, upd = _update_query_status(queries_rows, qrow["id"], "running", started_at=now_iso)
    if not ok:
        return upd  # error object

    # Offline deterministic-ish synthetic series based on params
    # Build buckets based on unit
    def _bucket_step(u):
        if u == "day":
            return datetime.timedelta(days=1)
        if u == "week":
            return datetime.timedelta(days=7)
        # month: step by month boundaries
        return None

    buckets = []
    if unit in ("day", "week"):
        step = _bucket_step(unit)
        d = fd
        while d <= td:
            buckets.append(d)
            d = (datetime.datetime.combine(d, datetime.time()) + step).date()
    else:
        # month buckets by first of month
        d = fd.replace(day=1)
        while d <= td:
            buckets.append(d)
            y = d.year + (1 if d.month == 12 else 0)
            m = 1 if d.month == 12 else (d.month + 1)
            d = datetime.date(y, m, 1)

    # stable base using cache_key or workspace_id+range
    seed_src = (cache_key or (workspace_id + "|" + from_date + "|" + to_date + "|" + unit + "|" + type + "|" + ",".join(event_names)))
    seed_int = int(hashlib.sha256(seed_src.encode("utf-8")).hexdigest()[:8], 16)
    rng = random.Random(seed_int)

    series = []
    for b in buckets:
        # include only buckets overlapping window for month buckets
        if unit == "month":
            # bucket represents month start; include if month intersects [fd, td]
            month_start = b
            y = month_start.year + (1 if month_start.month == 12 else 0)
            m = 1 if month_start.month == 12 else (month_start.month + 1)
            month_end = datetime.date(y, m, 1) - datetime.timedelta(days=1)
            if month_end < fd or month_start > td:
                continue

        base = rng.randint(0, 250)
        if type == "unique":
            value = int(base * 0.6)
        elif type == "average":
            value = round(base / max(1, rng.randint(20, 120)), 4)
        else:
            value = base

        series.append({"date": b.isoformat(), "value": value})

    payload = {
        "workspace_id": workspace_id,
        "project_id": ws.get("mixpanel_project_id"),
        "region": ws.get("region"),
        "from_date": from_date,
        "to_date": to_date,
        "unit": unit,
        "type": type,
        "events": event_names,
        "series": series
    }

    res_row, res_err = _create_result_row(qrow, payload, cache_key, cache_ttl_seconds)
    if res_err:
        _update_query_status(queries_rows, qrow["id"], "failed", completed_at=now_iso, duration_ms=_ms(), error_code=res_err["error"]["code"], error_message=res_err["error"]["message"])
        return res_err

    _update_query_status(queries_rows, qrow["id"], "succeeded", completed_at=now_iso, duration_ms=_ms(), http_status=200)

    # Update api key last_used_at
    keys = _load("workspace_api_keys.json")
    for k in keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("workspace_api_keys.json", keys)

    return {"query": qrow, "result": {"id": res_row.get("id"), "status": res_row.get("status"), "expires_at": res_row.get("expires_at")}, "data": payload}

def aggregated_event_property_values(workspace_id, event, property, from_date, to_date, unit, type, limit=None, cache_ttl_seconds=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"
    def _ms():
        return int((time.time() - t0) * 1000)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _parse_date(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int.from_bytes(os.urandom(11), "big")
        out = []
        for _ in range(17):
            x, r = divmod(x, 36)
            out.append(alphabet[r])
        return prefix + "_" + "".join(reversed(out))

    def _canonical_json(obj):
        if obj is None:
            obj = {}
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _cache_key(ws_id, qtype, params):
        h = hashlib.sha256((ws_id + "|" + qtype + "|" + _canonical_json(params)).encode("utf-8")).hexdigest()
        return "ck_" + h

    def _evict_expired(results):
        changed = False
        for r in results:
            if r.get("status") == "fresh" and r.get("expires_at"):
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp <= now_dt:
                    r["status"] = "stale"
                    r["updated_at"] = now_iso
                    changed = True
        if changed:
            _save("analytics_query_results.json", results)

    def _pick_authorized_context(ws_id):
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws:
            return None, None, _err("NOT_FOUND", "Workspace connection not found.", workspace_id=ws_id)
        keys = _load("workspace_api_keys.json")
        candidates = []
        for k in keys:
            if k.get("workspace_id") != ws_id or k.get("status") != "active":
                continue
            scopes = k.get("scopes") or []
            if isinstance(scopes, list) and ("read:reports" in scopes):
                candidates.append(k)
        if candidates:
            candidates.sort(key=lambda r: (int(r.get("rate_limit_per_minute") or 0), int(r.get("daily_quota") or 0)), reverse=True)
            return ws, candidates[0], None
        any_key = next((k for k in keys if k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if any_key:
            return ws, any_key, None
        return None, None, _err("UNAUTHORIZED", "No active API key available to serve this request for the workspace.", workspace_id=ws_id)

    def _check_limits(api_key_row, queries_rows):
        if not api_key_row:
            return None
        key_id = api_key_row.get("id")
        if not key_id:
            return _err("UNAUTHORIZED", "API key context missing.")
        rpm = api_key_row.get("rate_limit_per_minute")
        dq = api_key_row.get("daily_quota")
        try:
            rpm = int(rpm)
            dq = int(dq)
        except Exception:
            return _err("VALIDATION_ERROR", "API key limits misconfigured.", api_key_id=key_id)

        window_1m = now_dt - datetime.timedelta(minutes=1)
        window_1d = now_dt - datetime.timedelta(days=1)
        c1m = 0
        c1d = 0
        for q in queries_rows:
            if q.get("api_key_id") != key_id:
                continue
            ca = _parse_dt(q.get("created_at"))
            if not ca:
                continue
            if ca >= window_1m:
                c1m += 1
            if ca >= window_1d:
                c1d += 1
        if c1m >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", api_key_id=key_id, limit_per_minute=rpm)
        if c1d >= dq:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", api_key_id=key_id, daily_quota=dq)
        return None

    # Validate (accept ids longer than 17 to match actual datastore)
    if not isinstance(workspace_id, str) or not re.fullmatch(r"^mix_ws_[0-9A-Z]{17,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(event, str) or event.strip() == "":
        return _err("VALIDATION_ERROR", "event must be a non-empty string.")
    if not isinstance(property, str) or property.strip() == "":
        return _err("VALIDATION_ERROR", "property must be a non-empty string.")
    fd = _parse_date(from_date)
    td = _parse_date(to_date)
    if not fd:
        return _err("VALIDATION_ERROR", "from_date must be YYYY-MM-DD.")
    if not td:
        return _err("VALIDATION_ERROR", "to_date must be YYYY-MM-DD.")
    if fd > td:
        return _err("VALIDATION_ERROR", "from_date must be on or before to_date.")
    if unit not in ("day", "week", "month"):
        return _err("VALIDATION_ERROR", "unit must be one of: day, week, month.")
    if type not in ("general", "unique", "average"):
        return _err("VALIDATION_ERROR", "type must be one of: general, unique, average.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 1000):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.")
    if cache_ttl_seconds is None:
        cache_ttl_seconds = 0
    if not isinstance(cache_ttl_seconds, int) or not (0 <= cache_ttl_seconds <= 2592000):
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer between 0 and 2592000.")

    params = {
        "workspace_id": workspace_id,
        "event": event,
        "property": property,
        "from_date": from_date,
        "to_date": to_date,
        "unit": unit,
        "type": type,
        "limit": limit,
        "cache_ttl_seconds": cache_ttl_seconds,
    }

    ws, api_key, ctx_err = _pick_authorized_context(workspace_id)
    if ctx_err:
        return ctx_err

    queries = _load("analytics_queries.json")
    results = _load("analytics_query_results.json")
    _evict_expired(results)

    ck = None
    ttl = None
    if cache_ttl_seconds and cache_ttl_seconds > 0:
        ck = _cache_key(workspace_id, "events.segmentation", {"event": event, "property": property, "from_date": from_date, "to_date": to_date, "unit": unit, "type": type, "limit": limit})
        ttl = cache_ttl_seconds
        for r in results:
            if r.get("cache_key") == ck and r.get("workspace_id") == workspace_id and r.get("status") == "fresh":
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp > now_dt:
                    qid = _gen_id("mix_qry")
                    qrow = {
                        "id": qid,
                        "workspace_id": workspace_id,
                        "api_key_id": api_key.get("id") if api_key else None,
                        "tool_name": "aggregated_event_property_values",
                        "query_type": "events.segmentation",
                        "parameters": params,
                        "mixpanel_request": None,
                        "cache_key": ck,
                        "cache_ttl_seconds": ttl,
                        "status": "succeeded",
                        "started_at": now_iso,
                        "completed_at": now_iso,
                        "duration_ms": 0,
                        "http_status": 200,
                        "error_code": None,
                        "error_message": None,
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    queries.append(qrow)
                    _save("analytics_queries.json", queries)
                    if api_key:
                        api_key["last_used_at"] = now_iso
                        api_key["updated_at"] = now_iso
                        keys = _load("workspace_api_keys.json")
                        for i, k in enumerate(keys):
                            if k.get("id") == api_key.get("id"):
                                keys[i] = api_key
                                _save("workspace_api_keys.json", keys)
                                break
                    payload = r.get("result_json") if r.get("content_type") == "application/json" else {"text": r.get("result_text")}
                    return {"query": qrow, "cached": True, "data": payload, "meta": {"latency_ms": _ms()}}

    qid = _gen_id("mix_qry")
    qrow = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": api_key.get("id") if api_key else None,
        "tool_name": "aggregated_event_property_values",
        "query_type": "events.segmentation",
        "parameters": params,
        "mixpanel_request": {"endpoint": "/events/segmentation", "querystring": {"event": event, "property": property, "from_date": from_date, "to_date": to_date, "unit": unit, "type": type, "limit": limit}, "region": ws.get("region")},
        "cache_key": ck,
        "cache_ttl_seconds": ttl,
        "status": "queued",
        "started_at": None,
        "completed_at": None,
        "duration_ms": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    lim_err = _check_limits(api_key, queries)
    if lim_err:
        qrow["status"] = "failed"
        qrow["started_at"] = now_iso
        qrow["completed_at"] = now_iso
        qrow["duration_ms"] = 0
        qrow["error_code"] = lim_err["error"]["code"].lower()
        qrow["error_message"] = lim_err["error"]["message"]
        qrow["updated_at"] = now_iso
        queries.append(qrow)
        _save("analytics_queries.json", queries)
        return lim_err

    queries.append(qrow)
    _save("analytics_queries.json", queries)

    qrow["status"] = "running"
    qrow["started_at"] = now_iso
    qrow["updated_at"] = now_iso
    for i in range(len(queries) - 1, -1, -1):
        if queries[i].get("id") == qid:
            queries[i] = qrow
            _save("analytics_queries.json", queries)
            break

    if ws.get("status") != "active":
        qrow["status"] = "failed"
        qrow["completed_at"] = now_iso
        qrow["duration_ms"] = _ms()
        qrow["http_status"] = 424
        qrow["error_code"] = "workspace_inactive"
        qrow["error_message"] = "Workspace connection is not active; refusing to contact Mixpanel."
        qrow["updated_at"] = now_iso
        for i in range(len(queries) - 1, -1, -1):
            if queries[i].get("id") == qid:
                queries[i] = qrow
                _save("analytics_queries.json", queries)
                break
        return _err("INVALID_TRANSITION", qrow["error_message"], workspace_id=workspace_id, workspace_status=ws.get("status"))

    # buckets
    def _iter_buckets(start, end, unit_):
        cur = start
        while cur <= end:
            yield cur
            if unit_ == "day":
                cur = cur + datetime.timedelta(days=1)
            elif unit_ == "week":
                cur = cur + datetime.timedelta(days=7)
            else:
                y, m = cur.year, cur.month + 1
                if m == 13:
                    y += 1
                    m = 1
                d = min(cur.day, [31, 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1])
                cur = datetime.date(y, m, d)

    bucket_dates = list(_iter_buckets(fd, td, unit))
    # top property values (deterministic)
    base_seed = hashlib.sha256((workspace_id + "|" + event + "|" + property).encode("utf-8")).hexdigest()
    prop_values = [f"{property}_value_{i+1}" for i in range(min(limit, 50))]
    segments = {}
    for pv_i, pv in enumerate(prop_values[:limit]):
        seed = hashlib.sha256((base_seed + "|" + pv + "|" + from_date + "|" + to_date + "|" + unit + "|" + type).encode("utf-8")).hexdigest()
        pts = []
        for j, d in enumerate(bucket_dates):
            base = int(seed[(j * 2) % len(seed)], 16) + 1
            if type == "unique":
                val = base
            elif type == "average":
                val = round(base / 4.0, 4)
            else:
                val = base * 3
            pts.append({"date": d.isoformat(), "value": val})
        segments[pv] = pts

    data = {"event": event, "property": property, "from_date": from_date, "to_date": to_date, "unit": unit, "type": type, "limit": limit, "segments": segments}

    qrow["status"] = "succeeded"
    qrow["completed_at"] = now_iso
    qrow["duration_ms"] = _ms()
    qrow["http_status"] = 200
    qrow["updated_at"] = now_iso
    for i in range(len(queries) - 1, -1, -1):
        if queries[i].get("id") == qid:
            queries[i] = qrow
            _save("analytics_queries.json", queries)
            break

    res_id = _gen_id("mix_res")
    expires_at = None
    if cache_ttl_seconds and cache_ttl_seconds > 0:
        expires_at = (now_dt + datetime.timedelta(seconds=cache_ttl_seconds)).isoformat() + "Z"
    res_row = {
        "id": res_id,
        "query_id": qid,
        "workspace_id": workspace_id,
        "cache_key": ck,
        "content_type": "application/json",
        "result_json": data,
        "result_text": None,
        "result_bytes": len(json.dumps(data, ensure_ascii=False).encode("utf-8")),
        "status": "fresh",
        "expires_at": expires_at,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    if any(r.get("query_id") == qid for r in results):
        return _err("CONFLICT", "Result for query already exists (unique(query_id)).", query_id=qid)
    results.append(res_row)
    _save("analytics_query_results.json", results)

    if api_key:
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        keys = _load("workspace_api_keys.json")
        for i, k in enumerate(keys):
            if k.get("id") == api_key.get("id"):
                keys[i] = api_key
                _save("workspace_api_keys.json", keys)
                break

    return {"query": qrow, "cached": False, "data": data, "meta": {"latency_ms": _ms()}}

def query_insights_report(workspace_id, report_id, from_date=None, to_date=None, cache_ttl_seconds=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"
    def _ms():
        return int((time.time() - t0) * 1000)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _parse_date(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int.from_bytes(os.urandom(11), "big")
        out = []
        for _ in range(17):
            x, r = divmod(x, 36)
            out.append(alphabet[r])
        return prefix + "_" + "".join(reversed(out))

    def _canonical_json(obj):
        if obj is None:
            obj = {}
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _cache_key(ws_id, qtype, params):
        h = hashlib.sha256((ws_id + "|" + qtype + "|" + _canonical_json(params)).encode("utf-8")).hexdigest()
        return "ck_" + h

    def _evict_expired(results):
        changed = False
        for r in results:
            if r.get("status") == "fresh" and r.get("expires_at"):
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp <= now_dt:
                    r["status"] = "stale"
                    r["updated_at"] = now_iso
                    changed = True
        if changed:
            _save("analytics_query_results.json", results)

    def _pick_authorized_context(ws_id):
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws:
            return None, None, _err("NOT_FOUND", "Workspace connection not found.", workspace_id=ws_id)
        keys = _load("workspace_api_keys.json")
        candidates = []
        for k in keys:
            if k.get("workspace_id") != ws_id or k.get("status") != "active":
                continue
            scopes = k.get("scopes") or []
            if isinstance(scopes, list) and ("read:reports" in scopes):
                candidates.append(k)
        if candidates:
            candidates.sort(key=lambda r: (int(r.get("rate_limit_per_minute") or 0), int(r.get("daily_quota") or 0)), reverse=True)
            return ws, candidates[0], None
        any_key = next((k for k in keys if k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if any_key:
            return ws, any_key, None
        return None, None, _err("UNAUTHORIZED", "No active API key available to serve this request for the workspace.", workspace_id=ws_id)

    def _check_limits(api_key_row, queries_rows):
        if not api_key_row:
            return None
        key_id = api_key_row.get("id")
        if not key_id:
            return _err("UNAUTHORIZED", "API key context missing.")
        rpm = api_key_row.get("rate_limit_per_minute")
        dq = api_key_row.get("daily_quota")
        try:
            rpm = int(rpm)
            dq = int(dq)
        except Exception:
            return _err("VALIDATION_ERROR", "API key limits misconfigured.", api_key_id=key_id)

        window_1m = now_dt - datetime.timedelta(minutes=1)
        window_1d = now_dt - datetime.timedelta(days=1)
        c1m = 0
        c1d = 0
        for q in queries_rows:
            if q.get("api_key_id") != key_id:
                continue
            ca = _parse_dt(q.get("created_at"))
            if not ca:
                continue
            if ca >= window_1m:
                c1m += 1
            if ca >= window_1d:
                c1d += 1
        if c1m >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", api_key_id=key_id, limit_per_minute=rpm)
        if c1d >= dq:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", api_key_id=key_id, daily_quota=dq)
        return None

    # Validate (accept ids longer than 17 to match actual datastore)
    if not isinstance(workspace_id, str) or not re.fullmatch(r"^mix_ws_[0-9A-Z]{17,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(report_id, str) or report_id.strip() == "":
        return _err("VALIDATION_ERROR", "report_id must be a non-empty string.")
