    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int.from_bytes(os.urandom(11), "big")
        out = []
        for _ in range(17):
            x, r = divmod(x, 36)
            out.append(alphabet[r])
        return prefix + "_" + "".join(reversed(out))

    def _canonical_json(obj):
        if obj is None:
            obj = {}
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _cache_key(ws_id, qtype, params):
        h = hashlib.sha256((ws_id + "|" + qtype + "|" + _canonical_json(params)).encode("utf-8")).hexdigest()
        return "ck_" + h

    def _evict_expired(results):
        changed = False
        for r in results:
            if r.get("status") == "fresh" and r.get("expires_at"):
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp <= now_dt:
                    r["status"] = "stale"
                    r["updated_at"] = now_iso
                    changed = True
        if changed:
            _save("analytics_query_results.json", results)

    def _pick_authorized_context(ws_id):
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws:
            return None, None, _err("NOT_FOUND", "Workspace connection not found.", workspace_id=ws_id)
        keys = _load("workspace_api_keys.json")
        candidates = []
        for k in keys:
            if k.get("workspace_id") != ws_id or k.get("status") != "active":
                continue
            scopes = k.get("scopes") or []
            if isinstance(scopes, list) and ("read:reports" in scopes):
                candidates.append(k)
        if candidates:
            candidates.sort(key=lambda r: (int(r.get("rate_limit_per_minute") or 0), int(r.get("daily_quota") or 0)), reverse=True)
            return ws, candidates[0], None
        any_key = next((k for k in keys if k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if any_key:
            return ws, any_key, None
        return None, None, _err("UNAUTHORIZED", "No active API key available to serve this request for the workspace.", workspace_id=ws_id)

    def _check_limits(api_key_row, queries_rows):
        if not api_key_row:
            return None
        key_id = api_key_row.get("id")
        if not key_id:
            return _err("UNAUTHORIZED", "API key context missing.")
        rpm = api_key_row.get("rate_limit_per_minute")
        dq = api_key_row.get("daily_quota")
        try:
            rpm = int(rpm)
            dq = int(dq)
        except Exception:
            return _err("VALIDATION_ERROR", "API key limits misconfigured.", api_key_id=key_id)

        window_1m = now_dt - datetime.timedelta(minutes=1)
        window_1d = now_dt - datetime.timedelta(days=1)
        c1m = 0
        c1d = 0
        for q in queries_rows:
            if q.get("api_key_id") != key_id:
                continue
            ca = _parse_dt(q.get("created_at"))
            if not ca:
                continue
            if ca >= window_1m:
                c1m += 1
            if ca >= window_1d:
                c1d += 1
        if c1m >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", api_key_id=key_id, limit_per_minute=rpm)
        if c1d >= dq:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", api_key_id=key_id, daily_quota=dq)
        return None

    # Validate (accept ids longer than 17 to match actual datastore)
    if not isinstance(workspace_id, str) or not re.fullmatch(r"^mix_ws_[0-9A-Z]{17,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(funnel_id, str) or funnel_id.strip() == "":
        return _err("VALIDATION_ERROR", "funnel_id must be a non-empty string.")
    fd = _parse_date(from_date)
    td = _parse_date(to_date)
    if not fd:
        return _err("VALIDATION_ERROR", "from_date must be YYYY-MM-DD.")
    if not td:
        return _err("VALIDATION_ERROR", "to_date must be YYYY-MM-DD.")
    if fd > td:
        return _err("VALIDATION_ERROR", "from_date must be on or before to_date.")
    if cache_ttl_seconds is None:
        cache_ttl_seconds = 0
    if not isinstance(cache_ttl_seconds, int) or not (0 <= cache_ttl_seconds <= 2592000):
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer between 0 and 2592000.")

    params = {"workspace_id": workspace_id, "funnel_id": funnel_id, "from_date": from_date, "to_date": to_date, "cache_ttl_seconds": cache_ttl_seconds}

    ws, api_key, ctx_err = _pick_authorized_context(workspace_id)
    if ctx_err:
        return ctx_err

    # Validate referenced funnel_id exists in cache OR allow ad-hoc vendor-ish IDs (business rule)
    entities = _load("mixpanel_entities.json")
    exists = any(
        e.get("workspace_id") == workspace_id and e.get("entity_type") == "funnel" and e.get("mixpanel_entity_id") == funnel_id and e.get("status") != "deleted"
        for e in entities
    )
    # allow ad-hoc: numeric ids or UUID-ish / opaque ids
    adhoc_allowed = bool(re.fullmatch(r"^[0-9]{1,20}$", funnel_id)) or bool(re.fullmatch(r"^[A-Za-z0-9_\-]{6,64}$", funnel_id))
    if not exists and not adhoc_allowed:
        # must record failed analytics_queries row
        queries = _load("analytics_queries.json")
        qid = _gen_id("mix_qry")
        qrow = {
            "id": qid,
            "workspace_id": workspace_id,
            "api_key_id": api_key.get("id") if api_key else None,
            "tool_name": "query_funnel_report",
            "query_type": "funnels.report",
            "parameters": params,
            "mixpanel_request": None,
            "cache_key": None,
            "cache_ttl_seconds": None,
            "status": "failed",
            "started_at": now_iso,
            "completed_at": now_iso,
            "duration_ms": 0,
            "http_status": 404,
            "error_code": "unknown_funnel_id",
            "error_message": "Referenced funnel_id is not available for this workspace (not found in cached entities and not an allowed ad-hoc id).",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        queries.append(qrow)
        _save("analytics_queries.json", queries)
        return _err("NOT_FOUND", qrow["error_message"], workspace_id=workspace_id, funnel_id=funnel_id)

    queries = _load("analytics_queries.json")
    results = _load("analytics_query_results.json")
    _evict_expired(results)

    ck = None
    ttl = None
    if cache_ttl_seconds and cache_ttl_seconds > 0:
        ck = _cache_key(workspace_id, "funnels.report", {"funnel_id": funnel_id, "from_date": from_date, "to_date": to_date})
        ttl = cache_ttl_seconds
        for r in results:
            if r.get("cache_key") == ck and r.get("workspace_id") == workspace_id and r.get("status") == "fresh":
                exp = _parse_dt(r.get("expires_at"))
                if exp and exp > now_dt:
                    qid = _gen_id("mix_qry")
                    qrow = {
                        "id": qid,
                        "workspace_id": workspace_id,
                        "api_key_id": api_key.get("id") if api_key else None,
                        "tool_name": "query_funnel_report",
                        "query_type": "funnels.report",
                        "parameters": params,
                        "mixpanel_request": None,
                        "cache_key": ck,
                        "cache_ttl_seconds": ttl,
                        "status": "succeeded",
                        "started_at": now_iso,
                        "completed_at": now_iso,
                        "duration_ms": 0,
                        "http_status": 200,
                        "error_code": None,
                        "error_message": None,
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    queries.append(qrow)
                    _save("analytics_queries.json", queries)
                    if api_key:
                        api_key["last_used_at"] = now_iso
                        api_key["updated_at"] = now_iso
                        keys = _load("workspace_api_keys.json")
                        for i, k in enumerate(keys):
                            if k.get("id") == api_key.get("id"):
                                keys[i] = api_key
                                _save("workspace_api_keys.json", keys)
                                break
                    payload = r.get("result_json") if r.get("content_type") == "application/json" else {"text": r.get("result_text")}
                    return {"query": qrow, "cached": True, "data": payload, "meta": {"latency_ms": _ms()}}

    qid = _gen_id("mix_qry")
    qrow = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": api_key.get("id") if api_key else None,
        "tool_name": "query_funnel_report",
        "query_type": "funnels.report",
        "parameters": params,
        "mixpanel_request": {"endpoint": "/funnels", "querystring": {"funnel_id": funnel_id, "from_date": from_date, "to_date": to_date}, "region": ws.get("region")},
        "cache_key": ck,
        "cache_ttl_seconds": ttl,
        "status": "queued",
        "started_at": None,
        "completed_at": None,
        "duration_ms": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    lim_err = _check_limits(api_key, queries)
    if lim_err:
        qrow["status"] = "failed"
        qrow["started_at"] = now_iso
        qrow["completed_at"] = now_iso
        qrow["duration_ms"] = 0
        qrow["error_code"] = lim_err["error"]["code"].lower()
        qrow["error_message"] = lim_err["error"]["message"]
        qrow["updated_at"] = now_iso
        queries.append(qrow)
        _save("analytics_queries.json", queries)
        return lim_err

    queries.append(qrow)
    _save("analytics_queries.json", queries)

    qrow["status"] = "running"
    qrow["started_at"] = now_iso
    qrow["updated_at"] = now_iso
    for i in range(len(queries) - 1, -1, -1):
        if queries[i].get("id") == qid:
            queries[i] = qrow
            _save("analytics_queries.json", queries)
            break

    if ws.get("status") != "active":
        qrow["status"] = "failed"
        qrow["completed_at"] = now_iso
        qrow["duration_ms"] = _ms()
        qrow["http_status"] = 424
        qrow["error_code"] = "workspace_inactive"
        qrow["error_message"] = "Workspace connection is not active; refusing to contact Mixpanel."
        qrow["updated_at"] = now_iso
        for i in range(len(queries) - 1, -1, -1):
            if queries[i].get("id") == qid:
                queries[i] = qrow
                _save("analytics_queries.json", queries)
                break
        return _err("INVALID_TRANSITION", qrow["error_message"], workspace_id=workspace_id, workspace_status=ws.get("status"))

    seed = hashlib.sha256((workspace_id + "|" + funnel_id + "|" + from_date + "|" + to_date).encode("utf-8")).hexdigest()
    steps = []
    remaining = 1000
    for i in range(5):
        drop = int(seed[(i * 2) % len(seed)], 16) * 5
        remaining = max(0, remaining - drop)
        steps.append({"step": i + 1, "count": remaining})
    data = {"funnel_id": funnel_id, "from_date": from_date, "to_date": to_date, "steps": steps}

    qrow["status"] = "succeeded"
    qrow["completed_at"] = now_iso
    qrow["duration_ms"] = _ms()
    qrow["http_status"] = 200
    qrow["updated_at"] = now_iso
    for i in range(len(queries) - 1, -1, -1):
        if queries[i].get("id") == qid:
            queries[i] = qrow
            _save("analytics_queries.json", queries)
            break

    res_id = _gen_id("mix_res")
    expires_at = None
    if cache_ttl_seconds and cache_ttl_seconds > 0:
        expires_at = (now_dt + datetime.timedelta(seconds=cache_ttl_seconds)).isoformat() + "Z"
    res_row = {
        "id": res_id,
        "query_id": qid,
        "workspace_id": workspace_id,
        "cache_key": ck,
        "content_type": "application/json",
        "result_json": data,
        "result_text": None,
        "result_bytes": len(json.dumps(data, ensure_ascii=False).encode("utf-8")),
        "status": "fresh",
        "expires_at": expires_at,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    if any(r.get("query_id") == qid for r in results):
        return _err("CONFLICT", "Result for query already exists (unique(query_id)).", query_id=qid)
    results.append(res_row)
    _save("analytics_query_results.json", results)

    if api_key:
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        keys = _load("workspace_api_keys.json")
        for i, k in enumerate(keys):
            if k.get("id") == api_key.get("id"):
                keys[i] = api_key
                _save("workspace_api_keys.json", keys)
                break

    return {"query": qrow, "cached": False, "data": data, "meta": {"latency_ms": _ms()}}

def list_saved_funnels(workspace_id, length_unit=None, limit=None, cursor=None, cache_ttl_seconds=None, **_extra):
    import json, os, datetime, re, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"
    def _ms():
        return int((time.time() - t0) * 1000)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int.from_bytes(os.urandom(11), "big")
        out = []
        for _ in range(17):
            x, r = divmod(x, 36)
            out.append(alphabet[r])
        return prefix + "_" + "".join(reversed(out))

    # Validate (accept ids longer than 17 to match actual datastore)
    if not isinstance(workspace_id, str) or not re.fullmatch(r"^mix_ws_[0-9A-Z]{17,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if length_unit is not None and length_unit not in ("day", "week", "month"):
        return _err("VALIDATION_ERROR", "length_unit must be one of: day, week, month.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or not (1 <= limit <= 500):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
    if cache_ttl_seconds is None:
        cache_ttl_seconds = 0
    if not isinstance(cache_ttl_seconds, int) or not (0 <= cache_ttl_seconds <= 2592000):
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer between 0 and 2592000.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Always create analytics_queries row (business rule)
    queries = _load("analytics_queries.json")
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        # Still record query attempt as failed per business rule
        qid = _gen_id("mix_qry")
        qrow = {
            "id": qid,
            "workspace_id": workspace_id,
            "api_key_id": None,
            "tool_name": "list_saved_funnels",
            "query_type": "entities.list",
            "parameters": {"workspace_id": workspace_id, "length_unit": length_unit, "limit": limit, "cursor": cursor, "cache_ttl_seconds": cache_ttl_seconds},
            "mixpanel_request": None,
            "cache_key": None,
            "cache_ttl_seconds": None,
            "status": "failed",
            "started_at": now_iso,
            "completed_at": now_iso,
            "duration_ms": 0,
            "http_status": 404,
            "error_code": "workspace_not_found",
            "error_message": "Workspace connection not found.",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        queries.append(qrow)
        _save("analytics_queries.json", queries)
        return _err("NOT_FOUND", "Workspace connection not found.", workspace_id=workspace_id)

    qid = _gen_id("mix_qry")
    qrow = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": None,
        "tool_name": "list_saved_funnels",
        "query_type": "entities.list",
        "parameters": {"workspace_id": workspace_id, "length_unit": length_unit, "limit": limit, "cursor": cursor, "cache_ttl_seconds": cache_ttl_seconds},
        "mixpanel_request": None,
        "cache_key": None,
        "cache_ttl_seconds": None,
        "status": "succeeded",
        "started_at": now_iso,
        "completed_at": now_iso,
        "duration_ms": 0,
        "http_status": 200,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    queries.append(qrow)
    _save("analytics_queries.json", queries)

    # Read from mixpanel_entities where entity_type matches and status != deleted
    ents = _load("mixpanel_entities.json")
    rows = [e for e in ents if e.get("workspace_id") == workspace_id and e.get("entity_type") == "funnel" and e.get("status") != "deleted"]
    # stable sort: active first, then stale; name then id
    def _skey(e):
        st = e.get("status")
        st_rank = 0 if st == "active" else 1
        return (st_rank, (e.get("name") or "").lower(), (e.get("mixpanel_entity_id") or ""))
    rows.sort(key=_skey)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{offset+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Do not create analytics_query_results for list tools (business rules only require list read from entities)
    return {
        "query": qrow,
        "data": {
            "funnels": [
                {
                    "id": r.get("mixpanel_entity_id"),
                    "name": r.get("name"),
                    "status": r.get("status"),
                    "definition": r.get("definition"),
                    "last_seen_at": r.get("last_seen_at"),
                }
                for r in page
            ]
        },
        "meta": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "latency_ms": _ms()},
    }

def list_saved_cohorts(workspace_id, include_definition=None, status=None, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^mix_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if include_definition is not None and not isinstance(include_definition, bool):
        return _err("VALIDATION_ERROR", "include_definition must be a boolean")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "stale", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, stale, deleted")
    if search is not None and not isinstance(search, str):
        return _err("VALIDATION_ERROR", "search must be a string")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is not None:
        if not isinstance(sort, str) or sort not in ("name", "last_seen_at", "updated_at", "created_at"):
            return _err("VALIDATION_ERROR", "sort must be one of: name, last_seen_at, updated_at, created_at")
    if order is not None:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    # defaults
    include_definition = bool(include_definition) if include_definition is not None else False
    sort = sort or "name"
    order = order or "asc"
    limit = limit if limit is not None else 100

    # ---- load store ----
    workspaces = _load("workspaces.json")
    entities = _load("mixpanel_entities.json")
    queries = _load("analytics_queries.json")

    # ---- resolve workspace & enforce active ----
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)

    # Create analytics_queries row for every call
    def _gen_id(prefix):
        # prefix like "mix_q_"
        raw = f"{prefix}{now.timestamp()}_{os.getpid()}_{len(queries)+1}".encode("utf-8")
        return prefix + base64.b32encode(hashlib.sha256(raw).digest())[:26].decode("ascii").rstrip("=").upper()

    qid = _gen_id("mix_q_")
    params_obj = {
        "workspace_id": workspace_id,
        "include_definition": include_definition,
        "status": status,
        "search": search,
        "limit": limit,
        "cursor": cursor,
        "sort": sort,
        "order": order,
    }

    query_row = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": None,
        "tool_name": "list_saved_cohorts",
        "query_type": "entities.list",
        "parameters": params_obj,
        "mixpanel_request": None,
        "cache_key": None,
        "cache_ttl_seconds": None,
        "status": "succeeded",  # entities.list is not a Mixpanel read per rules
        "started_at": None,
        "completed_at": now_iso,
        "duration_ms": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    if ws is None:
        queries.append({**query_row, "status": "failed", "error_code": "workspace_not_found", "error_message": "Workspace not found"})
        _save("analytics_queries.json", queries)
        return _err("NOT_FOUND", "Workspace not found", query_id=qid)

    if ws.get("status") != "active":
        queries.append({**query_row, "status": "failed", "error_code": "workspace_inactive", "error_message": "Workspace is not active"})
        _save("analytics_queries.json", queries)
        return {
            "query_id": qid,
            "status": "failed",
            "error": {"code": "INVALID_TRANSITION", "message": "Workspace is not active"},
        }

    # ---- pagination cursor decoding ----
    offset = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(decoded.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("workspace_id") != workspace_id:
                raise ValueError("bad cursor")
            offset = obj.get("offset")
            if not isinstance(offset, int) or offset < 0:
                raise ValueError("bad offset")
            # ensure cursor ties to sort/order/search/status/limit to prevent inconsistencies
            for k in ("sort", "order", "search", "status"):
                if obj.get(k) != params_obj.get(k):
                    raise ValueError("cursor does not match query")
        except Exception:
            queries.append({**query_row, "status": "failed", "error_code": "invalid_cursor", "error_message": "Invalid cursor"})
            _save("analytics_queries.json", queries)
            return _err("VALIDATION_ERROR", "cursor is invalid", query_id=qid)

    # ---- filter, search, sort ----
    rows = [e for e in entities if e.get("workspace_id") == workspace_id and e.get("entity_type") == "cohort"]
    # rule: list reads where status != 'deleted'
    rows = [e for e in rows if e.get("status") != "deleted"]
    if status is not None:
        # Even if asked deleted, deleted are not returned by tool rule; so it will be empty.
        rows = [e for e in rows if e.get("status") == status and e.get("status") != "deleted"]
    if search:
        s = search.casefold()
        rows = [e for e in rows if isinstance(e.get("name"), str) and s in e.get("name").casefold()]

    def _dt_key(v):
        if not v:
            return None
        if isinstance(v, str):
            try:
                # allow trailing Z
                vv = v[:-1] if v.endswith("Z") else v
                return datetime.datetime.fromisoformat(vv)
            except Exception:
                return None
        return None

    def _sort_key(e):
        if sort == "name":
            return (e.get("name") or "").casefold()
        if sort == "last_seen_at":
            return _dt_key(e.get("last_seen_at")) or datetime.datetime.min
        if sort == "updated_at":
            return _dt_key(e.get("updated_at")) or datetime.datetime.min
        if sort == "created_at":
            return _dt_key(e.get("created_at")) or datetime.datetime.min
        return (e.get("name") or "").casefold()

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total

    next_cursor = None
    if has_more:
        cur_obj = {"v": 1, "workspace_id": workspace_id, "offset": next_offset, "sort": sort, "order": order, "search": search, "status": status}
        enc = base64.urlsafe_b64encode(json.dumps(cur_obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    def _shape(e):
        out = {
            "id": e.get("id"),
            "workspace_id": e.get("workspace_id"),
            "entity_type": e.get("entity_type"),
            "mixpanel_entity_id": e.get("mixpanel_entity_id"),
            "name": e.get("name"),
            "status": e.get("status"),
            "last_seen_at": e.get("last_seen_at"),
            "created_at": e.get("created_at"),
            "updated_at": e.get("updated_at"),
        }
        if include_definition:
            out["definition"] = e.get("definition")
        return out

    result_rows = [_shape(e) for e in page]

    # finalize query row
    duration_ms = int((time.time() - t0) * 1000)
    query_row["duration_ms"] = duration_ms
    query_row["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    queries.append(query_row)
    _save("analytics_queries.json", queries)

    return {
        "query_id": qid,
        "data": result_rows,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "offset": offset,
        },
        "status": "succeeded",
    }

def query_retention_report(workspace_id, from_date, to_date, retention_type=None, born_event=None, event=None, born_where=None, where=None, on=None, interval=None, unit=None, cache_ttl_seconds=None, use_cache=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^mix_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed")
    if not isinstance(from_date, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", from_date):
        return _err("VALIDATION_ERROR", "from_date must be YYYY-MM-DD")
    if not isinstance(to_date, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", to_date):
        return _err("VALIDATION_ERROR", "to_date must be YYYY-MM-DD")
    try:
        fd = datetime.date.fromisoformat(from_date)
        td = datetime.date.fromisoformat(to_date)
        if td < fd:
            return _err("VALIDATION_ERROR", "to_date must be on or after from_date")
    except Exception:
        return _err("VALIDATION_ERROR", "from_date/to_date must be valid dates")

    if born_event is None or not isinstance(born_event, str) or born_event == "":
        return _err("VALIDATION_ERROR", "born_event is required and must be a non-empty string")
    if event is None or not isinstance(event, str) or event == "":
        return _err("VALIDATION_ERROR", "event is required and must be a non-empty string")

    if retention_type is not None and (not isinstance(retention_type, str) or retention_type not in ("birth", "compounded")):
        return _err("VALIDATION_ERROR", "retention_type must be one of: birth, compounded")
    if born_where is not None and not isinstance(born_where, str):
        return _err("VALIDATION_ERROR", "born_where must be a string")
    if where is not None and not isinstance(where, str):
        return _err("VALIDATION_ERROR", "where must be a string")
    if on is not None and (not isinstance(on, str) or on not in ("properties", "distinct_id")):
        return _err("VALIDATION_ERROR", "on must be one of: properties, distinct_id")
    if interval is not None:
        if not isinstance(interval, int) or interval < 1:
            return _err("VALIDATION_ERROR", "interval must be an integer >= 1")
    if unit is not None:
        if not isinstance(unit, str) or unit not in ("day", "week", "month"):
            return _err("VALIDATION_ERROR", "unit must be one of: day, week, month")
    if cache_ttl_seconds is not None:
        if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 0:
            return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer >= 0")
        if cache_ttl_seconds > 86400:
            return _err("VALIDATION_ERROR", "cache_ttl_seconds must be between 0 and 86400")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean")

    # mutual exclusivity enforced in parameters when present
    if interval is not None and unit is not None:
        return _err("VALIDATION_ERROR", "Only one of interval or unit may be provided")

    use_cache = True if use_cache is None else use_cache
    requested_ttl = cache_ttl_seconds if cache_ttl_seconds is not None else 0

    # ---- load store ----
    workspaces = _load("workspaces.json")
    keys = _load("workspace_api_keys.json")
    queries = _load("analytics_queries.json")
    results = _load("analytics_query_results.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)

    # pick an active key for quota/rate enforcement if any exist (ambient auth)
    def _find_serving_key():
        active = [k for k in keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"]
        # choose the one with highest limits to maximize chance of serving
        def _score(k):
            rl = k.get("rate_limit_per_minute") or 0
            dq = k.get("daily_quota") or 0
            return (rl, dq)
        active.sort(key=_score, reverse=True)
        return active[0] if active else None

    api_key = _find_serving_key()
    api_key_id = api_key.get("id") if api_key else None

    # helper: ids
    def _gen_id(prefix):
        raw = f"{prefix}{now.timestamp()}_{os.getpid()}_{len(queries)+len(results)+1}".encode("utf-8")
        return prefix + base64.b32encode(hashlib.sha256(raw).digest())[:26].decode("ascii").rstrip("=").upper()

    # canonical params for cache key
    params_obj = {
        "workspace_id": workspace_id,
        "from_date": from_date,
        "to_date": to_date,
        "retention_type": retention_type,
        "born_event": born_event,
        "event": event,
        "born_where": born_where,
        "where": where,
        "on": on,
        "interval": interval,
        "unit": unit,
        "cache_ttl_seconds": cache_ttl_seconds,
        "use_cache": use_cache,
    }

    def _cache_key():
        canonical = {
            "from_date": from_date,
            "to_date": to_date,
            "retention_type": retention_type,
            "born_event": born_event,
            "event": event,
            "born_where": born_where,
            "where": where,
            "on": on,
            "interval": interval,
            "unit": unit,
        }
        s = json.dumps({"workspace_id": workspace_id, "query_type": "retention.report", "p": canonical}, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    ck = _cache_key()
    now_dt = now

    # result retention: mark expired as stale
    changed_results = False
    for r in results:
        if r.get("status") == "fresh" and r.get("expires_at"):
            try:
                ex = r["expires_at"]
                ex_dt = datetime.datetime.fromisoformat(ex[:-1] if isinstance(ex, str) and ex.endswith("Z") else ex)
                if ex_dt <= now_dt:
                    r["status"] = "stale"
                    r["updated_at"] = now_iso
                    changed_results = True
            except Exception:
                pass
    if changed_results:
        _save("analytics_query_results.json", results)

    # if cache allowed and fresh result exists, return it (still must create analytics_queries row)
    fresh = None
    if use_cache:
        for r in results:
            if r.get("cache_key") == ck and r.get("status") == "fresh" and r.get("expires_at"):
                try:
                    ex = r["expires_at"]
                    ex_dt = datetime.datetime.fromisoformat(ex[:-1] if ex.endswith("Z") else ex)
                    if ex_dt > now_dt:
                        fresh = r
                        break
                except Exception:
                    continue

    qid = _gen_id("mix_q_")

    # rate limit / quota check (only if a key exists; if none exist anywhere, UNAUTHORIZED)
    if api_key is None:
        # still record failed query row
        query_row = {
            "id": qid,
            "workspace_id": workspace_id,
            "api_key_id": None,
            "tool_name": "query_retention_report",
            "query_type": "retention.report",
            "parameters": params_obj,
            "mixpanel_request": None,
            "cache_key": ck,
            "cache_ttl_seconds": requested_ttl if requested_ttl > 0 else None,
            "status": "failed",
            "started_at": now_iso,
            "completed_at": now_iso,
            "duration_ms": int((time.time() - t0) * 1000),
            "http_status": None,
            "error_code": "unauthorized",
            "error_message": "No active API key available for this workspace",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        queries.append(query_row)
        _save("analytics_queries.json", queries)
        return _err("UNAUTHORIZED", "No active API key available for this workspace", query_id=qid)

    # enforce workspace exists and active before "contacting Mixpanel"
    if ws is None:
        query_row = {
            "id": qid, "workspace_id": workspace_id, "api_key_id": api_key_id,
            "tool_name": "query_retention_report", "query_type": "retention.report",
            "parameters": params_obj, "mixpanel_request": None, "cache_key": ck,
            "cache_ttl_seconds": requested_ttl if requested_ttl > 0 else None,
            "status": "failed", "started_at": now_iso, "completed_at": now_iso,
            "duration_ms": int((time.time() - t0) * 1000),
            "http_status": None, "error_code": "workspace_not_found",
            "error_message": "Workspace not found",
            "created_at": now_iso, "updated_at": now_iso,
        }
        queries.append(query_row)
        _save("analytics_queries.json", queries)
        return _err("NOT_FOUND", "Workspace not found", query_id=qid)

    if ws.get("status") != "active":
        query_row = {
            "id": qid, "workspace_id": workspace_id, "api_key_id": api_key_id,
            "tool_name": "query_retention_report", "query_type": "retention.report",
            "parameters": params_obj, "mixpanel_request": None, "cache_key": ck,
            "cache_ttl_seconds": requested_ttl if requested_ttl > 0 else None,
            "status": "failed", "started_at": now_iso, "completed_at": now_iso,
            "duration_ms": int((time.time() - t0) * 1000),
            "http_status": None, "error_code": "workspace_inactive",
            "error_message": "Workspace is not active",
            "created_at": now_iso, "updated_at": now_iso,
        }
        queries.append(query_row)
        _save("analytics_queries.json", queries)
        return {
            "query_id": qid,
            "status": "failed",
            "error": {"code": "INVALID_TRANSITION", "message": "Workspace is not active"},
        }

    # check rate limits based on analytics_queries created in last minute/day for this key
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
        except Exception:
            return None

    last_minute = 0
    last_day = 0
    for q in queries:
        if q.get("api_key_id") != api_key_id:
            continue
        created = _parse_dt(q.get("created_at"))
        if not created:
            continue
        if created >= minute_ago:
            last_minute += 1
        if created >= day_ago:
            last_day += 1

    rl = int(api_key.get("rate_limit_per_minute") or 0)
    dq = int(api_key.get("daily_quota") or 0)

    if rl and last_minute >= rl:
        query_row = {
            "id": qid, "workspace_id": workspace_id, "api_key_id": api_key_id,
            "tool_name": "query_retention_report", "query_type": "retention.report",
            "parameters": params_obj, "mixpanel_request": None, "cache_key": ck,
            "cache_ttl_seconds": requested_ttl if requested_ttl > 0 else None,
            "status": "failed", "started_at": now_iso, "completed_at": now_iso,
            "duration_ms": int((time.time() - t0) * 1000),
            "http_status": None, "error_code": "rate_limit",
            "error_message": "Rate limit exceeded",
            "created_at": now_iso, "updated_at": now_iso,
        }
        queries.append(query_row)
        _save("analytics_queries.json", queries)
        return _err("RATE_LIMIT", "Rate limit exceeded", query_id=qid, retry_after_seconds=60)

    if dq and last_day >= dq:
        query_row = {
            "id": qid, "workspace_id": workspace_id, "api_key_id": api_key_id,
            "tool_name": "query_retention_report", "query_type": "retention.report",
            "parameters": params_obj, "mixpanel_request": None, "cache_key": ck,
            "cache_ttl_seconds": requested_ttl if requested_ttl > 0 else None,
            "status": "failed", "started_at": now_iso, "completed_at": now_iso,
            "duration_ms": int((time.time() - t0) * 1000),
            "http_status": None, "error_code": "daily_quota",
            "error_message": "Daily quota exceeded",
            "created_at": now_iso, "updated_at": now_iso,
        }
        queries.append(query_row)
        _save("analytics_queries.json", queries)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", query_id=qid)

    # Create query row (queued -> running -> succeeded/failed)
    query_row = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "tool_name": "query_retention_report",
        "query_type": "retention.report",
        "parameters": params_obj,
        "mixpanel_request": {"endpoint": "/retention", "region": ws.get("region"), "project_id": ws.get("mixpanel_project_id")},
        "cache_key": ck,
        "cache_ttl_seconds": requested_ttl if requested_ttl > 0 else None,
        "status": "queued",
        "started_at": None,
        "completed_at": None,
        "duration_ms": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    queries.append(query_row)
    _save("analytics_queries.json", queries)

    # If cache hit, return cached without executing; still transition status as succeeded quickly
    if fresh is not None:
        # transition to running then succeeded
        for q in queries:
            if q.get("id") == qid:
                q["status"] = "running"
                q["started_at"] = now_iso
                q["updated_at"] = now_iso
                break
        _save("analytics_queries.json", queries)
        done_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        dur = int((time.time() - t0) * 1000)
        for q in queries:
            if q.get("id") == qid:
                q["status"] = "succeeded"
                q["completed_at"] = done_iso
                q["duration_ms"] = dur
                q["http_status"] = 200
                q["updated_at"] = done_iso
                break
        api_key["last_used_at"] = done_iso
        api_key["updated_at"] = done_iso
        # persist key update
        for i, k in enumerate(keys):
            if k.get("id") == api_key_id:
                keys[i] = api_key
                break
        _save("workspace_api_keys.json", keys)
        _save("analytics_queries.json", queries)
        return {
            "query_id": qid,
            "status": "succeeded",
            "cached": True,
            "data": fresh.get("result_json") if fresh.get("content_type") == "application/json" else fresh.get("result_text"),
            "content_type": fresh.get("content_type"),
            "cache": {"cache_key": ck, "expires_at": fresh.get("expires_at")},
        }

    # "Execute" Mixpanel call (offline): generate deterministic synthetic payload
    # transition queued->running
    run_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for q in queries:
        if q.get("id") == qid:
            q["status"] = "running"
            q["started_at"] = run_iso
            q["updated_at"] = run_iso
            break
    _save("analytics_queries.json", queries)

    try:
        # build cohorts and intervals length
        horizon_days = (td - fd).days + 1
        if unit:
            step = {"day": 1, "week": 7, "month": 30}[unit]
        else:
            step = int(interval or 1)
        buckets = max(1, (horizon_days + step - 1) // step)
        seed_material = json.dumps({"ck": ck, "buckets": buckets}, sort_keys=True).encode("utf-8")
        seed = int(hashlib.sha256(seed_material).hexdigest()[:8], 16)
        rng = random.Random(seed)

        # Simple retention-like matrix: cohorts x buckets with decreasing values
        cohorts = min(12, max(1, (horizon_days + 6) // 7))
        data = []
        for c in range(cohorts):
            start_users = rng.randint(80, 500)
            row = []
            current = start_users
            for b in range(buckets):
                if b == 0:
                    row.append(current)
                else:
                    decay = rng.uniform(0.55, 0.92)
                    current = int(current * decay)
                    row.append(current)
            data.append(row)

        payload = {
            "type": retention_type or "birth",
            "from_date": from_date,
            "to_date": to_date,
            "born_event": born_event,
            "event": event,
            "unit": unit or f"{interval}d",
            "series": data,
            "meta": {"cohorts": cohorts, "buckets": buckets},
        }

        # store result if ttl > 0
        expires_at = None
        if requested_ttl and requested_ttl > 0:
            expires_at_dt = datetime.datetime.utcnow().replace(microsecond=0) + datetime.timedelta(seconds=requested_ttl)
            expires_at = expires_at_dt.isoformat() + "Z"

        done_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        dur = int((time.time() - t0) * 1000)

        # transition to succeeded
        for q in queries:
            if q.get("id") == qid:
                q["status"] = "succeeded"
                q["completed_at"] = done_iso
                q["duration_ms"] = dur
                q["http_status"] = 200
                q["updated_at"] = done_iso
                break

        # create analytics_query_results (unique query_id)
        rid = _gen_id("mix_r_")
        if any(r.get("query_id") == qid for r in results):
            # should not happen; treat as conflict
            for q in queries:
                if q.get("id") == qid:
                    q["status"] = "failed"
                    q["error_code"] = "result_conflict"
                    q["error_message"] = "Result row already exists for query_id"
                    q["http_status"] = 500
                    q["updated_at"] = done_iso
                    break
            _save("analytics_queries.json", queries)
            return _err("CONFLICT", "Result already exists for query_id", query_id=qid)

        if requested_ttl and requested_ttl > 0:
            result_row = {
                "id": rid,
                "query_id": qid,
                "workspace_id": workspace_id,
                "cache_key": ck,
                "content_type": "application/json",
                "result_json": payload,
                "result_text": None,
                "result_bytes": len(json.dumps(payload, ensure_ascii=False).encode("utf-8")),
                "status": "fresh",
                "expires_at": expires_at,
                "created_at": done_iso,
                "updated_at": done_iso,
            }
            results.append(result_row)
            _save("analytics_query_results.json", results)

        # update key last_used_at on successful request
        api_key["last_used_at"] = done_iso
        api_key["updated_at"] = done_iso
        for i, k in enumerate(keys):
            if k.get("id") == api_key_id:
                keys[i] = api_key
                break
        _save("workspace_api_keys.json", keys)
        _save("analytics_queries.json", queries)

        return {
            "query_id": qid,
            "status": "succeeded",
            "cached": False,
            "content_type": "application/json",
            "data": payload,
            "cache": {"cache_key": ck, "expires_at": expires_at} if (requested_ttl and requested_ttl > 0) else {"cache_key": ck, "expires_at": None},
        }
    except Exception as e:
        done_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        dur = int((time.time() - t0) * 1000)
        for q in queries:
            if q.get("id") == qid:
                q["status"] = "failed"
                q["completed_at"] = done_iso
                q["duration_ms"] = dur
                q["http_status"] = 500
                q["error_code"] = "execution_error"
                q["error_message"] = str(e)[:500]
                q["updated_at"] = done_iso
                break
        _save("analytics_queries.json", queries)
        return _err("CONFLICT", "Unexpected execution error", query_id=qid, detail=str(e)[:200])

def query_segmentation_sum(workspace_id, event, from_date, to_date, unit, on, where=None, segmentation_id=None, limit=None, cache_ttl_seconds=None, use_cache=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            # accept "...Z" or naive isoformat
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None

    def _parse_date_ymd(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.date.fromisoformat(s)
        except ValueError:
            return None

    def _gen_id(prefix):
        # mix_ws_ style exists; for query/result we use mix_qry_ / mix_res_
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        # 20 chars to resemble other ids
        n = int.from_bytes(os.urandom(12), "big")
        out = []
        for _ in range(20):
            out.append(alphabet[n % 36])
            n //= 36
        return prefix + "".join(out)

    def _canonical(obj):
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _hash_cache_key(workspace_id, query_type, params_obj):
        h = hashlib.sha256()
        h.update(_canonical({"workspace_id": workspace_id, "query_type": query_type, "parameters": params_obj}).encode("utf-8"))
        return "ck_" + h.hexdigest()

    def _enforce_types_and_constraints():
        # workspace_id pattern
        if not isinstance(workspace_id, str) or not re.match(r"^mix_ws_[0-9A-Z]{18,}$", workspace_id):
            return _err("VALIDATION_ERROR", "workspace_id must match ^mix_ws_[0-9A-Z]{18,}$")
        if not isinstance(event, str) or event == "":
            return _err("VALIDATION_ERROR", "event must be a non-empty string")
        if not isinstance(on, str) or on == "":
            return _err("VALIDATION_ERROR", "on must be a non-empty string")
        d1 = _parse_date_ymd(from_date)
        if d1 is None:
            return _err("VALIDATION_ERROR", "from_date must be YYYY-MM-DD")
        d2 = _parse_date_ymd(to_date)
        if d2 is None:
            return _err("VALIDATION_ERROR", "to_date must be YYYY-MM-DD")
        if d2 < d1:
            return _err("VALIDATION_ERROR", "to_date must be on or after from_date")
        if unit not in ("day", "week", "month"):
            return _err("VALIDATION_ERROR", "unit must be one of: day, week, month")
        if where is not None and not isinstance(where, str):
            return _err("VALIDATION_ERROR", "where must be a string")
        if segmentation_id is not None and not isinstance(segmentation_id, str):
            return _err("VALIDATION_ERROR", "segmentation_id must be a string")
        if limit is not None:
            if not isinstance(limit, int):
                return _err("VALIDATION_ERROR", "limit must be an integer")
            if limit < 1 or limit > 200:
                return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        if cache_ttl_seconds is not None:
            if not isinstance(cache_ttl_seconds, int):
                return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer")
            if cache_ttl_seconds < 0:
                return _err("VALIDATION_ERROR", "cache_ttl_seconds must be >= 0")
        if use_cache is not None and not isinstance(use_cache, bool):
            return _err("VALIDATION_ERROR", "use_cache must be a boolean")
        return None

    started_monotonic = time.monotonic()
    now = _now()

    # Validate inputs first
    v = _enforce_types_and_constraints()
    if v:
        return v

    # Load data
    workspaces = _load("workspaces.json")
    api_keys = _load("workspace_api_keys.json")
    queries = _load("analytics_queries.json")
    results = _load("analytics_query_results.json")

    # Resolve workspace
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "workspace_id not found")

    # Ambient authentication: find some active key for workspace to enforce rate limits/quotas & attribute call
    # If none exist, treat as UNAUTHORIZED (no usable combination).
    usable_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"]
    api_key_row = None
    for k in usable_keys:
        if isinstance(k.get("rate_limit_per_minute"), int) and isinstance(k.get("daily_quota"), int):
            api_key_row = k
            break
    if api_key_row is None:
        return _err("UNAUTHORIZED", "No active API key available for this workspace")

    api_key_id = api_key_row.get("id")

    # Rate limit / quota enforcement (based on analytics_queries created timestamps)
    # last minute and last day counts for this api_key_id
    one_minute_ago = now - datetime.timedelta(minutes=1)
    day_ago = now - datetime.timedelta(days=1)
    per_minute = api_key_row.get("rate_limit_per_minute")
    daily_quota = api_key_row.get("daily_quota")

    def _count_since(dt):
        c = 0
        for q in queries:
            if not isinstance(q, dict):
                continue
            if q.get("api_key_id") != api_key_id:
                continue
            created = _parse_iso(q.get("created_at"))
            if created is None:
                continue
            if created >= dt:
                c += 1
        return c

    if isinstance(per_minute, int) and _count_since(one_minute_ago) >= per_minute:
        # Reject; do not create succeeded query
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key", limit=per_minute, window_seconds=60)
    if isinstance(daily_quota, int) and _count_since(day_ago) >= daily_quota:
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key", quota=daily_quota, window_seconds=86400)

    # Build exact parameters object as received ({} allowed, but here required fields exist)
    params = {
        "workspace_id": workspace_id,
        "event": event,
        "from_date": from_date,
        "to_date": to_date,
        "unit": unit,
        "where": where,
        "on": on,
        "segmentation_id": segmentation_id,
        "limit": limit,
        "cache_ttl_seconds": cache_ttl_seconds,
        "use_cache": use_cache,
    }
    # Strip Nones? Business rule says store exact JSON object received; since tool signature provides keys,
    # we store all fields including nulls for omitted optionals to preserve exact call shape.
    # (This is still a valid JSON object.)
    query_type = "events.segmentation"
    tool_name = "query_segmentation_sum"

    # Cache key handling
    ttl = None
    if cache_ttl_seconds is not None:
        ttl = cache_ttl_seconds
    cache_key = None
    if ttl is not None and ttl > 0:
        cache_key = _hash_cache_key(workspace_id, query_type, params)

    # Serve cached result if requested and available
    if use_cache is True and cache_key:
        # Mark expired results stale as part of observable dynamics
        mutated_results = False
        for r in results:
            if not isinstance(r, dict):
                continue
            if r.get("status") == "fresh":
                exp = _parse_iso(r.get("expires_at"))
                if exp is not None and exp <= now:
                    r["status"] = "stale"
                    r["updated_at"] = _iso(now)
                    mutated_results = True
        if mutated_results:
            _save("analytics_query_results.json", results)

        fresh = None
        for r in results:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != workspace_id:
                continue
            if r.get("cache_key") != cache_key:
                continue
            if r.get("status") != "fresh":
                continue
            exp = _parse_iso(r.get("expires_at"))
            if exp is None or exp <= now:
                continue
            fresh = r
            break

        if fresh is not None:
            # Still create an analytics_queries row for every tool call (even if cached)
            qid = _gen_id("mix_qry_")
            qrow = {
                "id": qid,
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "tool_name": tool_name,
                "query_type": query_type,
                "parameters": params,
                "mixpanel_request": {"source": "cache", "cache_key": cache_key},
                "cache_key": cache_key,
                "cache_ttl_seconds": ttl,
                "status": "succeeded",
                "started_at": _iso(now),
                "completed_at": _iso(now),
                "duration_ms": 0,
                "http_status": 200,
                "error_code": None,
                "error_message": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            queries.append(qrow)
            api_key_row["last_used_at"] = _iso(now)
            api_key_row["updated_at"] = _iso(now)
            _save("analytics_queries.json", queries)
            _save("workspace_api_keys.json", api_keys)

            payload = fresh.get("result_json") if fresh.get("content_type") == "application/json" else fresh.get("result_text")
            latency_ms = int((time.monotonic() - started_monotonic) * 1000)
            return {
                "query": qrow,
                "cached_result": True,
                "result": payload,
                "content_type": fresh.get("content_type"),
                "cache": {
                    "cache_key": cache_key,
                    "result_id": fresh.get("id"),
                    "expires_at": fresh.get("expires_at"),
                    "status": fresh.get("status"),
                },
                "latency_ms": latency_ms,
            }

    # Create analytics_queries row (queued)
    qid = _gen_id("mix_qry_")
    qrow = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "query_type": query_type,
        "parameters": params if isinstance(params, dict) else {},
        "mixpanel_request": None,
        "cache_key": cache_key,
        "cache_ttl_seconds": ttl,
        "status": "queued",
        "started_at": None,
        "completed_at": None,
        "duration_ms": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    queries.append(qrow)
    _save("analytics_queries.json", queries)

    # Enforce workspace status active before "contacting Mixpanel"
    if ws.get("status") != "active":
        # queued -> running -> failed (reads must transition); no Mixpanel call.
        running_at = _now()
        # transition to running
        qrow["status"] = "running"
        qrow["started_at"] = _iso(running_at)
        qrow["updated_at"] = _iso(running_at)
        # transition to failed
        done_at = _now()
        qrow["status"] = "failed"
        qrow["completed_at"] = _iso(done_at)
        qrow["duration_ms"] = int((time.monotonic() - started_monotonic) * 1000)
        qrow["http_status"] = None
        qrow["error_code"] = "workspace_inactive"
        qrow["error_message"] = f"Workspace status is '{ws.get('status')}', must be 'active'."
        qrow["updated_at"] = _iso(done_at)
        _save("analytics_queries.json", queries)
        return _err("INVALID_TRANSITION", "Workspace is not active; query execution blocked", query_id=qid)

    # Transition queued -> running
    running_at = _now()
    qrow["status"] = "running"
    qrow["started_at"] = _iso(running_at)
    qrow["updated_at"] = _iso(running_at)
    _save("analytics_queries.json", queries)

    # "Call Mixpanel": offline deterministic synthesized response (non-fabricated rows rule applies to DB rows, not external API)
    # Still record canonical request details without secrets.
    try:
        d1 = _parse_date_ymd(from_date)
        d2 = _parse_date_ymd(to_date)
        delta_days = (d2 - d1).days
        # prevent pathological generation
        if delta_days > 3660:
            raise ValueError("date range too large")
        # bucket dates by unit
        buckets = []
        if unit == "day":
            cur = d1
            while cur <= d2:
                buckets.append(cur.isoformat())
                cur = cur + datetime.timedelta(days=1)
        elif unit == "week":
            cur = d1
            while cur <= d2:
                buckets.append(cur.isoformat())
                cur = cur + datetime.timedelta(days=7)
        else:  # month
            cur = d1
            while cur <= d2:
                buckets.append(cur.isoformat())
                y, m = cur.year, cur.month
                if m == 12:
                    y2, m2 = y + 1, 1
                else:
                    y2, m2 = y, m + 1
                cur = datetime.date(y2, m2, 1)

        segs = []
        if segmentation_id:
            segs = ["$overall"]
            if limit is None:
                seg_limit = 10
            else:
                seg_limit = limit
            # generate deterministic segment labels
            for i in range(min(seg_limit, 10)):
                segs.append(f"{segmentation_id}:{i+1}")
        else:
            segs = ["$overall"]

        base = int(hashlib.sha256(_canonical(params).encode("utf-8")).hexdigest()[:8], 16)
        series = {}
        for s in segs:
            vals = {}
            for idx, b in enumerate(buckets):
                # deterministic pseudo-values
                v = ((base + idx * 1103515245 + (hash(s) & 0xFFFF)) % 10000) / 10.0
                vals[b] = v
            series[s] = vals

        result_payload = {
            "type": "segmentation_sum",
            "project_id": ws.get("mixpanel_project_id"),
            "event": event,
            "on": on,
            "unit": unit,
            "from_date": from_date,
            "to_date": to_date,
            "where": where,
            "segmentation_id": segmentation_id,
            "limit": limit,
            "data": series,
        }

        qrow["mixpanel_request"] = {
            "method": "GET",
            "endpoint": "/segmentation/sum",
            "region": ws.get("region"),
            "querystring": {
                "event": event,
                "from_date": from_date,
                "to_date": to_date,
                "unit": unit,
                "where": where,
                "on": on,
                "segmentation_id": segmentation_id,
                "limit": limit,
            },
            "headers": {"Accept": "application/json"},
        }

        # Transition running -> succeeded
        done_at = _now()
        qrow["status"] = "succeeded"
        qrow["completed_at"] = _iso(done_at)
        qrow["duration_ms"] = int((time.monotonic() - started_monotonic) * 1000)
        qrow["http_status"] = 200
        qrow["error_code"] = None
        qrow["error_message"] = None
        qrow["updated_at"] = _iso(done_at)

        # Create analytics_query_results with unique(query_id)
        # Ensure no existing result for query_id (shouldn't happen for new qid)
        if any(isinstance(r, dict) and r.get("query_id") == qid for r in results):
            # treat as conflict; mark query failed
            qrow["status"] = "failed"
            qrow["http_status"] = None
            qrow["error_code"] = "result_conflict"
            qrow["error_message"] = "A result row already exists for this query_id."
            qrow["updated_at"] = _iso(_now())
            _save("analytics_queries.json", queries)
            return _err("CONFLICT", "Result already exists for query_id", query_id=qid)

        content_text = json.dumps(result_payload, ensure_ascii=False, separators=(",", ":"))
        result_bytes = len(content_text.encode("utf-8"))

        expires_at = None
        status = "fresh"
        if ttl is None or ttl == 0:
            # if not caching, still store result but mark stale immediately (no TTL)
            status = "stale"
            expires_at = _iso(now)
        else:
            expires_at = _iso(now + datetime.timedelta(seconds=ttl))

        rid = _gen_id("mix_res_")
        rrow = {
            "id": rid,
            "query_id": qid,
            "workspace_id": workspace_id,
            "cache_key": cache_key,
            "content_type": "application/json",
            "result_json": result_payload,
            "result_text": None,
            "result_bytes": result_bytes,
            "status": status,
            "expires_at": expires_at,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        results.append(rrow)

        # Update key last_used_at on success
        api_key_row["last_used_at"] = _iso(done_at)
        api_key_row["updated_at"] = _iso(done_at)

        _save("analytics_queries.json", queries)
        _save("analytics_query_results.json", results)
        _save("workspace_api_keys.json", api_keys)

        return {
            "query": qrow,
            "cached_result": False,
            "result": result_payload,
            "content_type": "application/json",
            "cache": {
                "cache_key": cache_key,
                "ttl_seconds": ttl,
                "expires_at": expires_at,
                "result_id": rid,
                "status": status,
            },
        }

    except ValueError as e:
        # Handle expected generation/validation-like issues as failed query
        done_at = _now()
        qrow["status"] = "failed"
        if qrow.get("started_at") is None:
            qrow["started_at"] = _iso(running_at)
        qrow["completed_at"] = _iso(done_at)
        qrow["duration_ms"] = int((time.monotonic() - started_monotonic) * 1000)
        qrow["http_status"] = None
        qrow["error_code"] = "invalid_request"
        qrow["error_message"] = str(e)
        qrow["updated_at"] = _iso(done_at)
        _save("analytics_queries.json", queries)
        return _err("VALIDATION_ERROR", "Query failed", query_id=qid, details=str(e))
    except Exception as e:
        # Unexpected condition: return error object without raising
        done_at = _now()
        qrow["status"] = "failed"
        if qrow.get("started_at") is None:
            qrow["started_at"] = _iso(running_at)
        qrow["completed_at"] = _iso(done_at)
        qrow["duration_ms"] = int((time.monotonic() - started_monotonic) * 1000)
        qrow["http_status"] = None
        qrow["error_code"] = "internal_error"
        qrow["error_message"] = "Unexpected error during execution."
        qrow["updated_at"] = _iso(done_at)
        _save("analytics_queries.json", queries)
        return _err("CONFLICT", "Unexpected error during execution", query_id=qid, error=str(e))

def query_frequency_report(workspace_id, event, from_date, to_date, unit, where=None, segment=None, cache_ttl_seconds=None, use_cache=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _gen_id(prefix):
        raw = os.urandom(12)
        return f"{prefix}{base64.b32encode(raw).decode('ascii').rstrip('=' )}"

    def _canonical(obj):
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _cache_key(ws_id, qtype, params_obj):
        h = hashlib.sha256()
        h.update((ws_id + "|" + qtype + "|" + _canonical(params_obj)).encode("utf-8"))
        return "ck_" + h.hexdigest()

    def _record_query(queries, **fields):
        qid = _gen_id("mix_q_")
        row = {
            "id": qid,
            "workspace_id": fields["workspace_id"],
            "api_key_id": fields.get("api_key_id"),
            "tool_name": fields["tool_name"],
            "query_type": fields["query_type"],
            "parameters": fields["parameters"],
            "mixpanel_request": fields.get("mixpanel_request"),
            "cache_key": fields.get("cache_key"),
            "cache_ttl_seconds": fields.get("cache_ttl_seconds"),
            "status": fields.get("status", "queued"),
            "started_at": fields.get("started_at"),
            "completed_at": fields.get("completed_at"),
            "duration_ms": fields.get("duration_ms"),
            "http_status": fields.get("http_status"),
            "error_code": fields.get("error_code"),
            "error_message": fields.get("error_message"),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        queries.append(row)
        return row

    def _valid_date(s):
        if not isinstance(s, str):
            return False
        try:
            datetime.date.fromisoformat(s)
            return True
        except Exception:
            return False

    # ---------- Validate inputs ----------
    if not isinstance(workspace_id, str) or not re.match(r"^mix_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^mix_ws_[0-9A-Z]{18,}$")
    if not isinstance(event, str) or event == "":
        return _err("VALIDATION_ERROR", "event must be a non-empty string")
    if not _valid_date(from_date) or not _valid_date(to_date):
        return _err("VALIDATION_ERROR", "from_date and to_date must be YYYY-MM-DD")
    if not isinstance(unit, str) or unit not in ("day", "week", "month"):
        return _err("VALIDATION_ERROR", "unit must be one of: day, week, month")
    if where is not None and not isinstance(where, str):
        return _err("VALIDATION_ERROR", "where must be a string")
    if segment is not None and not isinstance(segment, str):
        return _err("VALIDATION_ERROR", "segment must be a string")
    if cache_ttl_seconds is not None:
        if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 0:
            return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer >= 0")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean")

    params_obj = {
        "event": event,
        "from_date": from_date,
        "to_date": to_date,
        "unit": unit,
    }
    if where is not None:
        params_obj["where"] = where
    if segment is not None:
        params_obj["segment"] = segment
    if cache_ttl_seconds is not None:
        params_obj["cache_ttl_seconds"] = cache_ttl_seconds
    if use_cache is not None:
        params_obj["use_cache"] = use_cache

    workspaces = _load("workspaces.json")
    keys = _load("workspace_api_keys.json")
    queries = _load("analytics_queries.json")
    results = _load("analytics_query_results.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        q = _record_query(
