        status="queued",
    )
    q["status"] = "running"
    q["started_at"] = now_iso
    q["updated_at"] = now_iso

    try:
        # deterministic empty buckets (offline), with computed bucket edges if min/max available
        bs = float(bucket_size)
        bc = int(bucket_count) if bucket_count is not None else 10
        buckets = []
        if min_value is not None and max_value is not None:
            start = float(min_value)
            for i in range(bc):
                lo = start + i * bs
                hi = lo + bs
                if lo > float(max_value):
                    break
                buckets.append({"min": lo, "max": hi, "count": 0})
        else:
            for i in range(bc):
                lo = i * bs
                buckets.append({"min": lo, "max": lo + bs, "count": 0})

        res_obj = {
            "event": event,
            "from_date": from_date,
            "to_date": to_date,
            "unit": unit,
            "on": on,
            "bucket_size": bs,
            "bucket_count": bc,
            "min_value": min_value,
            "max_value": max_value,
            "buckets": buckets,
        }

        q["status"] = "succeeded"
        q["http_status"] = 200
        q["completed_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        q["duration_ms"] = int((time.time() - t0) * 1000)
        q["updated_at"] = q["completed_at"]

        rid = _gen_id("mix_r_")
        expires_at = None
        if cache_ttl_seconds is not None and cache_ttl_seconds > 0:
            expires_at = (now + datetime.timedelta(seconds=cache_ttl_seconds)).isoformat()
        content = json.dumps(res_obj, ensure_ascii=False, separators=(",", ":"))
        rrow = {
            "id": rid,
            "query_id": q["id"],
            "workspace_id": workspace_id,
            "cache_key": cache_key,
            "content_type": "application/json",
            "result_json": res_obj,
            "result_text": None,
            "result_bytes": len(content.encode("utf-8")),
            "status": "fresh" if expires_at else "stale",
            "expires_at": expires_at,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        if any(r.get("query_id") == q["id"] for r in results):
            q["status"] = "failed"
            q["http_status"] = 500
            q["error_code"] = "conflict_result_exists"
            q["error_message"] = "Result already exists for query_id"
        else:
            results.append(rrow)
    except Exception as e:
        q["status"] = "failed"
        q["http_status"] = 500
        q["error_code"] = "internal_error"
        q["error_message"] = str(e)[:500]
        q["completed_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        q["duration_ms"] = int((time.time() - t0) * 1000)
        q["updated_at"] = q["completed_at"]

    _save("analytics_queries.json", queries)
    _save("analytics_query_results.json", results)
    if api_key_id and isinstance(key, dict) and key.get("status") == "active" and q.get("status") == "succeeded":
        key["last_used_at"] = now_iso
        key["updated_at"] = now_iso
        _save("workspace_api_keys.json", keys)

    if q.get("status") != "succeeded":
        return _err("CONFLICT" if q.get("error_code") == "conflict_result_exists" else "VALIDATION_ERROR", q.get("error_message") or "Query failed", query=q)

    return {"query": q, "cached": False, "result": res_obj}

def top_event_properties(workspace_id, event, from_date=None, to_date=None, limit=None, where=None, cache_ttl_seconds=None, use_cache=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(workspace_id, str) or not re.match(r"^mix_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
