    }

    done = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    duration_ms = int((time.time() - t0) * 1000)

    qrow["status"] = "succeeded"
    qrow["completed_at"] = done
    qrow["duration_ms"] = max(0, duration_ms)
    qrow["http_status"] = 200
    qrow["updated_at"] = done

    if any(r.get("query_id") == qid for r in results):
        qrow["status"] = "failed"
        qrow["error_code"] = "conflict_result_exists"
        qrow["error_message"] = "Result already exists for query_id."
        qrow["http_status"] = None
        qrow["updated_at"] = done
        _save("analytics_queries.json", queries)
        return _err("CONFLICT", "Result already exists for query_id.", query=qrow)

    rb = len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))
    expires_at = None
    if ttl is not None:
        expires_at = (datetime.datetime.utcnow() + datetime.timedelta(seconds=ttl)).replace(microsecond=0).isoformat() + "Z"

    rid = _new_id("mix_res")
    rrow = {
        "id": rid,
        "query_id": qid,
        "workspace_id": workspace_id,
        "cache_key": cache_key,
        "content_type": "application/json",
        "result_json": payload,
        "result_text": None,
        "result_bytes": rb,
        "status": "fresh",
        "expires_at": expires_at,
        "created_at": done,
        "updated_at": done,
    }
    results.append(rrow)
    _save("analytics_query_results.json", results)
    _save("analytics_queries.json", queries)

    if key:
        key["last_used_at"] = done
        key["updated_at"] = done
        _save("workspace_api_keys.json", keys)

    return {"query": qrow, "result": rrow, "cached": False}

def top_event_property_values(workspace_id, event, property_name, from_date=None, to_date=None, limit=None, where=None, cache_ttl_seconds=None, use_cache=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(workspace_id, str) or not re.match(r"^mix_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(event, str) or not event:
        return _err("VALIDATION_ERROR", "Invalid event.")
    if not isinstance(property_name, str) or not property_name:
        return _err("VALIDATION_ERROR", "Invalid property_name.")
    if from_date is not None and (not isinstance(from_date, str) or from_date == ""):
        return _err("VALIDATION_ERROR", "from_date must be a non-empty string when provided.")
    if to_date is not None and (not isinstance(to_date, str) or to_date == ""):
        return _err("VALIDATION_ERROR", "to_date must be a non-empty string when provided.")
    if from_date is not None:
        try: datetime.date.fromisoformat(from_date)
        except Exception: return _err("VALIDATION_ERROR", "from_date must be YYYY-MM-DD.")
    if to_date is not None:
        try: datetime.date.fromisoformat(to_date)
        except Exception: return _err("VALIDATION_ERROR", "to_date must be YYYY-MM-DD.")
    if from_date is not None and to_date is not None:
        if datetime.date.fromisoformat(to_date) < datetime.date.fromisoformat(from_date):
            return _err("VALIDATION_ERROR", "to_date must be on or after from_date.")
    if limit is not None:
        if not isinstance(limit, int) or not (1 <= limit <= 1000):
            return _err("VALIDATION_ERROR", "limit must be between 1 and 1000.")
    if where is not None and (not isinstance(where, str) or where == ""):
        return _err("VALIDATION_ERROR", "where must be a non-empty string when provided.")
    if cache_ttl_seconds is not None:
        if not isinstance(cache_ttl_seconds, int) or cache_ttl_seconds < 0:
            return _err("VALIDATION_ERROR", "cache_ttl_seconds must be an integer >= 0.")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.")

    workspaces = _load("workspaces.json")
    keys = _load("workspace_api_keys.json")
    queries = _load("analytics_queries.json")
    results = _load("analytics_query_results.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")

    key = next((k for k in keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    api_key_id = key.get("id") if key else None

    params_obj = {"workspace_id": workspace_id, "event": event, "property_name": property_name}
    if from_date is not None: params_obj["from_date"] = from_date
    if to_date is not None: params_obj["to_date"] = to_date
    if limit is not None: params_obj["limit"] = limit
    if where is not None: params_obj["where"] = where
    if cache_ttl_seconds is not None: params_obj["cache_ttl_seconds"] = cache_ttl_seconds
    if use_cache is not None: params_obj["use_cache"] = use_cache

    def _canon(o):
        return json.dumps(o, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    ttl = cache_ttl_seconds if (cache_ttl_seconds is not None and cache_ttl_seconds > 0) else None
    cache_key = None
    if ttl is not None:
        cache_key = hashlib.sha256((workspace_id + "|events.properties.top_values|" + _canon(params_obj)).encode("utf-8")).hexdigest()

    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            s2 = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    if use_cache is True and cache_key:
        dt_now = datetime.datetime.utcnow()
        changed = False
        for r in results:
            if r.get("status") == "fresh" and r.get("expires_at"):
                ex = _parse_dt(r.get("expires_at"))
                if ex and ex <= dt_now:
                    r["status"] = "stale"
                    r["updated_at"] = now
                    changed = True
        if changed:
            _save("analytics_query_results.json", results)

        cached = None
        for r in results:
            if r.get("cache_key") == cache_key and r.get("workspace_id") == workspace_id and r.get("status") == "fresh":
                ex = _parse_dt(r.get("expires_at"))
                if ex and ex > dt_now:
                    cached = r
                    break
        if cached:
            def _new_id(prefix):
                return prefix + "_" + hashlib.sha256((prefix + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
            qid = _new_id("mix_qry")
            qrow = {
                "id": qid,
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "tool_name": "top_event_property_values",
                "query_type": "events.properties.top_values",
                "parameters": params_obj,
                "mixpanel_request": {"cached": True, "cache_key": cache_key},
                "cache_key": cache_key,
                "cache_ttl_seconds": ttl,
                "status": "succeeded",
                "started_at": now,
                "completed_at": now,
                "duration_ms": 0,
                "http_status": 200,
                "error_code": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now,
            }
            queries.append(qrow)
            _save("analytics_queries.json", queries)
            if key:
                key["last_used_at"] = now
                key["updated_at"] = now
                _save("workspace_api_keys.json", keys)
            return {"query": qrow, "result": cached, "cached": True}

    if key:
        rl = key.get("rate_limit_per_minute")
        dq = key.get("daily_quota")
        if not isinstance(rl, int) or not isinstance(dq, int):
            return _err("UNAUTHORIZED", "No valid API key available for rate limiting.")
        dt_now = datetime.datetime.utcnow()
        one_min_ago = dt_now - datetime.timedelta(minutes=1)
        day_ago = dt_now - datetime.timedelta(days=1)

        def _dt(s):
            if not s: return None
            try:
                s2 = s[:-1] if isinstance(s, str) and s.endswith("Z") else s
                return datetime.datetime.fromisoformat(s2)
            except Exception:
                return None

        last_min = 0
        last_day = 0
        for q in queries:
            if q.get("api_key_id") != api_key_id:
                continue
            ca = _dt(q.get("created_at"))
            if not ca:
                continue
            if ca >= one_min_ago:
                last_min += 1
            if ca >= day_ago:
                last_day += 1
        if last_min >= rl:
            def _new_id(prefix):
                return prefix + "_" + hashlib.sha256((prefix + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
            qid = _new_id("mix_qry")
            qrow = {
                "id": qid,
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "tool_name": "top_event_property_values",
                "query_type": "events.properties.top_values",
                "parameters": params_obj,
                "mixpanel_request": None,
                "cache_key": cache_key,
                "cache_ttl_seconds": ttl,
                "status": "failed",
                "started_at": now,
                "completed_at": now,
                "duration_ms": 0,
                "http_status": None,
                "error_code": "rate_limit",
                "error_message": "Rate limit exceeded.",
                "created_at": now,
                "updated_at": now,
            }
            queries.append(qrow)
            _save("analytics_queries.json", queries)
            return _err("RATE_LIMIT", "Rate limit exceeded.", query=qrow)
        if last_day >= dq:
            def _new_id(prefix):
                return prefix + "_" + hashlib.sha256((prefix + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]
            qid = _new_id("mix_qry")
            qrow = {
                "id": qid,
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "tool_name": "top_event_property_values",
                "query_type": "events.properties.top_values",
                "parameters": params_obj,
                "mixpanel_request": None,
                "cache_key": cache_key,
                "cache_ttl_seconds": ttl,
                "status": "failed",
                "started_at": now,
                "completed_at": now,
                "duration_ms": 0,
                "http_status": None,
                "error_code": "daily_quota",
                "error_message": "Daily quota exceeded.",
                "created_at": now,
                "updated_at": now,
            }
            queries.append(qrow)
            _save("analytics_queries.json", queries)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", query=qrow)

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256((prefix + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]

    qid = _new_id("mix_qry")
    qrow = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "tool_name": "top_event_property_values",
        "query_type": "events.properties.top_values",
        "parameters": params_obj,
        "mixpanel_request": None,
        "cache_key": cache_key,
        "cache_ttl_seconds": ttl,
        "status": "queued",
        "started_at": None,
        "completed_at": None,
        "duration_ms": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    queries.append(qrow)
    _save("analytics_queries.json", queries)

    if ws.get("status") != "active":
        qrow["status"] = "failed"
        qrow["started_at"] = now
        qrow["completed_at"] = now
        qrow["duration_ms"] = 0
        qrow["error_code"] = "workspace_inactive"
        qrow["error_message"] = "Workspace is not active."
        qrow["updated_at"] = now
        _save("analytics_queries.json", queries)
        return _err("INVALID_TRANSITION", "Workspace is not active; cannot execute query.", query=qrow)

    qrow["status"] = "running"
    qrow["started_at"] = now
    qrow["updated_at"] = now
    qrow["mixpanel_request"] = {
        "endpoint": "events/properties/values/top",
        "region": ws.get("region"),
        "project_id": ws.get("mixpanel_project_id"),
        "query": {k: v for k, v in params_obj.items() if k not in ("workspace_id", "cache_ttl_seconds", "use_cache")},
    }
    _save("analytics_queries.json", queries)

    n = limit if limit is not None else 10
    vals = [{"value": f"value_{i+1}", "count": max(1, (n - i) * 7)} for i in range(min(n, 50))]
    payload = {
        "type": "top_event_property_values",
        "event": event,
        "property_name": property_name,
        "from_date": from_date,
        "to_date": to_date,
        "where": where,
