        "id": rid,
        "query_id": qid,
        "workspace_id": workspace_id,
        "cache_key": cache_key,
        "content_type": "application/json",
        "result_json": payload,
        "result_text": None,
        "result_bytes": rb,
        "status": "fresh",
        "expires_at": expires_at,
        "created_at": done,
        "updated_at": done,
    }
    results.append(rrow)
    _save("analytics_query_results.json", results)
    _save("analytics_queries.json", queries)

    if key:
        key["last_used_at"] = done
        key["updated_at"] = done
        _save("workspace_api_keys.json", keys)

    return {"query": qrow, "result": rrow, "cached": False}

def list_workspaces(status=None, region=None, auth_type=None, search=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, hashlib, base64, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # validate filters
    if status is not None and status not in ("active", "disabled", "error"):
        return _err("VALIDATION_ERROR", "Invalid status.")
    if region is not None and region not in ("US", "EU"):
        return _err("VALIDATION_ERROR", "Invalid region.")
    # tool schema enum says api_secret, but workspace schema uses project_token/basic_auth/service_account.
    # Accept both schema values and map api_secret -> basic_auth for compatibility.
    if auth_type is not None:
        if auth_type not in ("service_account", "api_secret", "project_token", "basic_auth"):
            return _err("VALIDATION_ERROR", "Invalid auth_type.")
    if search is not None:
        if not isinstance(search, str) or not (1 <= len(search) <= 200):
            return _err("VALIDATION_ERROR", "search must be a string of length 1..200.")
    if limit is not None:
        if not isinstance(limit, int) or not (1 <= limit <= 200):
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    workspaces = _load("workspaces.json")
    queries = _load("analytics_queries.json")  # observable dynamics: record call

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Pagination cursor: base64url(json {"o": offset, "h": hash(filters)})
    def _filters_sig():
        f = {"status": status, "region": region, "auth_type": auth_type, "search": search}
        s = json.dumps(f, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "o" not in obj or "h" not in obj:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if obj["h"] != _filters_sig():
                return _err("VALIDATION_ERROR", "Cursor does not match current filters.")
            if not isinstance(obj["o"], int) or obj["o"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor offset.")
            offset = obj["o"]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # filter rows
    at = auth_type
    if at == "api_secret":
        at = "basic_auth"
    filtered = []
    sneedle = search.lower() if isinstance(search, str) else None
    for w in workspaces:
        if status is not None and w.get("status") != status:
            continue
        if region is not None and w.get("region") != region:
            continue
        if at is not None and w.get("auth_type") != at:
            continue
        if sneedle is not None:
            nm = w.get("name") or ""
            if not isinstance(nm, str) or sneedle not in nm.lower():
                continue
        filtered.append(w)

    # stable sort by created_at then id
    def _dt(s):
        try:
            if isinstance(s, str) and s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s) if isinstance(s, str) else datetime.datetime(1970, 1, 1)
        except Exception:
            return datetime.datetime(1970, 1, 1)

    filtered.sort(key=lambda r: (_dt(r.get("created_at")), r.get("id") or ""))

    lim = limit if limit is not None else 50
    page = filtered[offset:offset + lim]
    next_off = offset + len(page)
    has_more = next_off < len(filtered)

    next_cursor = None
    if has_more:
        obj = {"o": next_off, "h": _filters_sig()}
        raw = json.dumps(obj, separators=(",", ":"), sort_keys=True).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Record an analytics_queries row for this tool call (business rule: every tool call)
    # list_workspaces is not in analytics_queries.tool_name enum; to avoid invalid data,
    # store under a closest allowed tool_name='list_saved_funnels' with query_type='entities.list'
    # and embed actual tool name in parameters.
    # This preserves observability without violating enum constraints.
    # If this is undesirable, the schema needs to include list_workspaces in tool_name enum.
    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256((prefix + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:24]

    qid = _new_id("mix_qry")
    qrow = {
        "id": qid,
        "workspace_id": page[0].get("id") if page else (filtered[0].get("id") if filtered else (workspaces[0].get("id") if workspaces else "mix_ws_UNKNOWN")),
        "api_key_id": None,
        "tool_name": "list_saved_funnels",
        "query_type": "entities.list",
        "parameters": {"_tool": "list_workspaces", "status": status, "region": region, "auth_type": auth_type, "search": search, "limit": limit, "cursor": cursor},
        "mixpanel_request": {"local_only": True},
        "cache_key": None,
        "cache_ttl_seconds": None,
        "status": "succeeded",
        "started_at": now,
        "completed_at": now,
        "duration_ms": 0,
        "http_status": 200,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    queries.append(qrow)
    _save("analytics_queries.json", queries)

    # redact secrets: never return auth_secret_ref
    def _sanitize(w):
        return {
            "id": w.get("id"),
            "name": w.get("name"),
            "mixpanel_project_id": w.get("mixpanel_project_id"),
            "service_account_label": w.get("service_account_label"),
            "auth_type": w.get("auth_type"),
            "region": w.get("region"),
            "timezone": w.get("timezone"),
            "default_length_unit": w.get("default_length_unit"),
            "status": w.get("status"),
            "last_successful_sync_at": w.get("last_successful_sync_at"),
            "last_error": w.get("last_error"),
            "created_at": w.get("created_at"),
            "updated_at": w.get("updated_at"),
        }

    return {
        "data": [_sanitize(w) for w in page],
        "pagination": {
            "total": len(filtered),
            "limit": lim,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
        "audit_query": qrow,
    }

def create_workspace(name, mixpanel_project_id, auth_type, auth_secret_ref, region, timezone, service_account_label=None, default_length_unit=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int.from_bytes(os.urandom(11), "big")
        out = []
        for _ in range(17):
            x, r = divmod(x, 36)
            out.append(alphabet[r])
        return prefix + "_" + "".join(reversed(out))

    # Validate input types/lengths
    if not isinstance(name, str) or not (1 <= len(name) <= 200) or name.strip() == "":
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 characters.", rule="name <> ''")
    if not isinstance(auth_secret_ref, str) or not (1 <= len(auth_secret_ref) <= 500) or auth_secret_ref.strip() == "":
        return _err("VALIDATION_ERROR", "auth_secret_ref must be a non-empty string up to 500 characters.")
    if region not in ("US", "EU"):
        return _err("VALIDATION_ERROR", "region must be one of: US, EU.")
    if not isinstance(timezone, str) or not (1 <= len(timezone) <= 64) or timezone.strip() == "":
        return _err("VALIDATION_ERROR", "timezone must be a non-empty string up to 64 characters.")
    if default_length_unit is None:
        default_length_unit = "day"
    if default_length_unit not in ("day", "week", "month"):
        return _err("VALIDATION_ERROR", "default_length_unit must be one of: day, week, month.")
    if service_account_label is not None:
        if not isinstance(service_account_label, str) or not (1 <= len(service_account_label) <= 200) or service_account_label.strip() == "":
            return _err("VALIDATION_ERROR", "service_account_label must be a non-empty string up to 200 characters.")

    # Tool schema differs from backend: tool passes mixpanel_project_id as string; backend stores integer > 0.
    mp_pid_int = None
    if isinstance(mixpanel_project_id, int):
        mp_pid_int = mixpanel_project_id
    elif isinstance(mixpanel_project_id, str):
        s = mixpanel_project_id.strip()
        if not s:
            return _err("VALIDATION_ERROR", "mixpanel_project_id must be a non-empty string or integer.")
        if not re.match(r"^[0-9]+$", s):
            # Accept non-numeric identifiers per tool schema, but backend requires integer > 0.
            # Map to validation error with declared backend constraint.
            return _err("VALIDATION_ERROR", "mixpanel_project_id must be a positive integer value.", rule="mixpanel_project_id > 0", mixpanel_project_id=mixpanel_project_id)
        try:
            mp_pid_int = int(s, 10)
        except Exception:
            return _err("VALIDATION_ERROR", "mixpanel_project_id must be a positive integer value.", rule="mixpanel_project_id > 0", mixpanel_project_id=mixpanel_project_id)
    else:
        return _err("VALIDATION_ERROR", "mixpanel_project_id must be a string or integer.", mixpanel_project_id=mixpanel_project_id)

    if not isinstance(mp_pid_int, int) or mp_pid_int <= 0:
        return _err("VALIDATION_ERROR", "mixpanel_project_id must be a positive integer.", rule="mixpanel_project_id > 0", mixpanel_project_id=mixpanel_project_id)

    # auth_type mapping: tool supports service_account/api_secret; backend enum is service_account/project_token/basic_auth.
    # Accept 'api_secret' as 'basic_auth' for compatibility (realistic migration), or keep service_account.
    if auth_type == "service_account":
        backend_auth_type = "service_account"
    elif auth_type == "api_secret":
        backend_auth_type = "basic_auth"
    else:
        return _err("VALIDATION_ERROR", "auth_type must be one of: service_account, api_secret.", auth_type=auth_type)

    # Load existing workspaces and enforce unique(mixpanel_project_id, region) as per backend constraint,
    # but only conflict if an ACTIVE connection already exists. If only disabled/error exists, allow creation.
    workspaces = _load("workspaces.json")
    existing_conflict = None
    for w in workspaces:
        if w.get("mixpanel_project_id") == mp_pid_int and w.get("region") == region:
            if w.get("status") == "active":
                existing_conflict = w
                break

    if existing_conflict is not None:
        return _err(
            "CONFLICT",
            "A workspace connection for this mixpanel_project_id and region already exists (unique(mixpanel_project_id, region) for active connections).",
            rule="unique(mixpanel_project_id, region)",
            mixpanel_project_id=mp_pid_int,
            region=region,
            existing_workspace_id=existing_conflict.get("id"),
            existing_status=existing_conflict.get("status")
        )

    now_iso = _now_iso()
    ws_id = _gen_id("mix_ws")
    row = {
        "id": ws_id,
        "name": name,
        "mixpanel_project_id": mp_pid_int,
        "service_account_label": service_account_label,
        "auth_type": backend_auth_type,
        "auth_secret_ref": auth_secret_ref,
        "region": region,
        "timezone": timezone,
        "default_length_unit": default_length_unit,
        "status": "active",
        "last_successful_sync_at": None,
        "last_error": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    workspaces.append(row)
    _save("workspaces.json", workspaces)

    return {"workspace": row}

def update_workspace(workspace_id, name=None, service_account_label=None, auth_secret_ref=None, region=None, timezone=None, default_length_unit=None, status=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate (accept ids longer than 17 to match actual datastore)
    if not isinstance(workspace_id, str) or not re.fullmatch(r"^mix_ws_[0-9A-Z]{17,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if name is not None and (not isinstance(name, str) or not (1 <= len(name) <= 200) or name.strip() == ""):
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 characters.")
    if service_account_label is not None and (not isinstance(service_account_label, str) or not (1 <= len(service_account_label) <= 200) or service_account_label.strip() == ""):
        return _err("VALIDATION_ERROR", "service_account_label must be a non-empty string up to 200 characters.")
    if auth_secret_ref is not None and (not isinstance(auth_secret_ref, str) or not (1 <= len(auth_secret_ref) <= 500) or auth_secret_ref.strip() == ""):
        return _err("VALIDATION_ERROR", "auth_secret_ref must be a non-empty string up to 500 characters.")
    if region is not None and region not in ("US", "EU"):
        return _err("VALIDATION_ERROR", "region must be one of: US, EU.")
    if timezone is not None and (not isinstance(timezone, str) or not (1 <= len(timezone) <= 64) or timezone.strip() == ""):
        return _err("VALIDATION_ERROR", "timezone must be a non-empty string up to 64 characters.")
    if default_length_unit is not None and default_length_unit not in ("day", "week", "month"):
        return _err("VALIDATION_ERROR", "default_length_unit must be one of: day, week, month.")
    if status is not None and status not in ("active", "disabled", "error"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, error.")

    workspaces = _load("workspaces.json")
    idx = None
    for i, w in enumerate(workspaces):
        if w.get("id") == workspace_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Workspace connection not found.", workspace_id=workspace_id)

    ws = dict(workspaces[idx])
    now_iso = _now_iso()

    # Apply updates
    changed = False
    if name is not None and name.strip() != ws.get("name"):
        ws["name"] = name.strip()
        changed = True
    if service_account_label is not None and service_account_label.strip() != (ws.get("service_account_label") or ""):
        ws["service_account_label"] = service_account_label.strip()
        changed = True
    if auth_secret_ref is not None and auth_secret_ref.strip() != ws.get("auth_secret_ref"):
        ws["auth_secret_ref"] = auth_secret_ref.strip()
        changed = True
    if timezone is not None and timezone.strip() != ws.get("timezone"):
        ws["timezone"] = timezone.strip()
        changed = True
    if default_length_unit is not None and default_length_unit != ws.get("default_length_unit"):
        ws["default_length_unit"] = default_length_unit
        changed = True

    # Region update must respect unique(mixpanel_project_id, region)
    if region is not None and region != ws.get("region"):
        mp_pid = ws.get("mixpanel_project_id")
        conflict = next((w for w in workspaces if w.get("id") != workspace_id and w.get("mixpanel_project_id") == mp_pid and w.get("region") == region), None)
        if conflict:
            return _err(
                "CONFLICT",
                "Updating region would violate unique(mixpanel_project_id, region).",
                mixpanel_project_id=mp_pid,
                region=region,
                existing_workspace_id=conflict.get("id"),
            )
        ws["region"] = region
        changed = True

    # Lifecycle transition
    if status is not None and status != ws.get("status"):
        cur = ws.get("status")
        allowed = {
            "active": {"disabled", "error"},
            "disabled": {"active"},
            "error": {"active", "disabled"},
        }
        if cur not in allowed or status not in allowed[cur]:
            return _err("INVALID_TRANSITION", "Requested status transition is not allowed by workspace lifecycle.", from_status=cur, to_status=status)
        ws["status"] = status
        changed = True

    if not changed:
        # No success without effect for mutations
        return _err("NOT_FOUND", "No changes to apply (request matched workspace but produced no updates).", workspace_id=workspace_id)

    ws["updated_at"] = now_iso
    workspaces[idx] = ws
    _save("workspaces.json", workspaces)
    return {"workspace": ws}

def list_workspace_api_keys(workspace_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _ms():
        return int((time.time() - t0) * 1000)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        x = int.from_bytes(os.urandom(11), "big")
        out = []
        for _ in range(17):
            x, r = divmod(x, 36)
            out.append(alphabet[r])
        return prefix + "_" + "".join(reversed(out))

    # Validate (accept ids longer than 17 to match actual datastore)
    if not isinstance(workspace_id, str) or not re.fullmatch(r"^mix_ws_[0-9A-Z]{17,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if status is not None and status not in ("active", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Record call in analytics_queries (business rule: every tool call)
    queries = _load("analytics_queries.json")
    qid = _gen_id("mix_qry")
    qrow = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": None,
        "tool_name": "list_workspace_api_keys",
        "query_type": "entities.list",
        "parameters": {"workspace_id": workspace_id, "status": status, "limit": limit, "cursor": cursor},
        "mixpanel_request": None,
        "cache_key": None,
        "cache_ttl_seconds": None,
        "status": "queued",
        "started_at": now_iso,
        "completed_at": now_iso,
        "duration_ms": 0,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        qrow["status"] = "failed"
        qrow["http_status"] = 404
        qrow["error_code"] = "workspace_not_found"
        qrow["error_message"] = "Workspace connection not found."
        queries.append(qrow)
        _save("analytics_queries.json", queries)
        return _err("NOT_FOUND", "Workspace connection not found.", workspace_id=workspace_id)

    keys = _load("workspace_api_keys.json")
    rows = [k for k in keys if k.get("workspace_id") == workspace_id and (status is None or k.get("status") == status)]
    rows.sort(key=lambda r: ((r.get("status") != "active"), (r.get("name") or "").lower(), r.get("id") or ""))

    total = len(rows)
    page = rows[offset:offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{offset+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    qrow["status"] = "succeeded"
    qrow["http_status"] = 200
    qrow["duration_ms"] = _ms()
    qrow["updated_at"] = now_iso
    queries.append(qrow)
    _save("analytics_queries.json", queries)

    # Never return raw key, only metadata (key_hash is ok)
    return {
        "query": qrow,
        "data": {
            "api_keys": [
                {
                    "id": k.get("id"),
                    "workspace_id": k.get("workspace_id"),
                    "name": k.get("name"),
                    "key_hash": k.get("key_hash"),
                    "scopes": k.get("scopes"),
                    "status": k.get("status"),
                    "rate_limit_per_minute": k.get("rate_limit_per_minute"),
                    "daily_quota": k.get("daily_quota"),
                    "last_used_at": k.get("last_used_at"),
                    "created_at": k.get("created_at"),
                    "updated_at": k.get("updated_at"),
                }
                for k in page
            ]
        },
        "meta": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
    }

def update_workspace_api_key(api_key_id, name=None, scopes=None, rate_limit_per_minute=None, daily_quota=None, status=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0365000" if __import__("os").path.isdir("./environment_mix/0365000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate (accept ids longer than 17 to match actual datastore)
    if not isinstance(api_key_id, str) or not re.fullmatch(r"^mix_key_[0-9A-Z]{17,}$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id is malformed.")
    if name is not None and (not isinstance(name, str) or not (1 <= len(name) <= 200) or name.strip() == ""):
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 characters.")
    allowed_scopes = {"read:entities", "read:reports", "exec:jql", "admin:keys"}
    if scopes is not None:
        if (not isinstance(scopes, list)) or len(scopes) < 1:
            return _err("VALIDATION_ERROR", "scopes must be a non-empty array.")
        for s in scopes:
            if s not in allowed_scopes:
                return _err("VALIDATION_ERROR", "Invalid scope in scopes.", scope=s)
        seen = set()
        scopes = [s for s in scopes if not (s in seen or seen.add(s))]
    if rate_limit_per_minute is not None and (not isinstance(rate_limit_per_minute, int) or not (1 <= rate_limit_per_minute <= 10000)):
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer between 1 and 10000.")
    if daily_quota is not None and (not isinstance(daily_quota, int) or not (1 <= daily_quota <= 1000000)):
        return _err("VALIDATION_ERROR", "daily_quota must be an integer between 1 and 1000000.")
    if status is not None and status not in ("active", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked.")

    keys = _load("workspace_api_keys.json")
    idx = None
    for i, k in enumerate(keys):
        if k.get("id") == api_key_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id)

    k = dict(keys[idx])
    now_iso = _now_iso()
    changed = False

    if name is not None and name.strip() != k.get("name"):
        # unique(workspace_id, name)
        wsid = k.get("workspace_id")
        conflict = next((r for r in keys if r.get("id") != api_key_id and r.get("workspace_id") == wsid and r.get("name") == name.strip()), None)
        if conflict:
            return _err("CONFLICT", "An API key with this name already exists for the workspace (unique(workspace_id, name)).", workspace_id=wsid, name=name.strip(), existing_api_key_id=conflict.get("id"))
        k["name"] = name.strip()
        changed = True

    if scopes is not None:
        k["scopes"] = scopes
        changed = True

    if rate_limit_per_minute is not None:
        k["rate_limit_per_minute"] = rate_limit_per_minute
        changed = True

    if daily_quota is not None:
        k["daily_quota"] = daily_quota
        changed = True

    if status is not None and status != k.get("status"):
        cur = k.get("status")
        if cur == "revoked":
            return _err("INVALID_TRANSITION", "Cannot transition a revoked key to another status.", from_status=cur, to_status=status)
        if cur == "active" and status != "revoked":
            return _err("INVALID_TRANSITION", "Only active->revoked is allowed for API keys.", from_status=cur, to_status=status)
        if cur == "active" and status == "revoked":
            k["status"] = "revoked"
            changed = True

    if not changed:
        return _err("NOT_FOUND", "No changes to apply (request matched api_key but produced no updates).", api_key_id=api_key_id)

    k["updated_at"] = now_iso
    keys[idx] = k
    _save("workspace_api_keys.json", keys)
    return {"api_key": k}
